import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum UserRole {
  GUEST = 'guest',
  CUSTOMER = 'customer',
  STAFF = 'staff',
  ADMIN = 'admin'
}

export interface Pool {
  id: string;
  match: string;
  teams: [string, string];
  flags: [string, string];
  league: string;
  prize: string;
  requirement?: string;
  status: 'live' | 'upcoming' | 'ended';
  time: string;
  pot?: string;
  image: string;
}

export interface User {
  username: string;
  points: number;
  avatar: string;
  rank: number;
}

import React, { useState } from 'react';
import { UserRole } from './types';
import LoginView from './views/LoginView';
import CustomerHome from './views/CustomerHome';
import StaffValidator from './views/StaffValidator';
import AdminDashboard from './views/AdminDashboard';
import CreatePool from './views/CreatePool';
import Leaderboard from './views/Leaderboard';
import Analytics from './views/Analytics';
import BrandCustomization from './views/BrandCustomization';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.GUEST);
  const [currentView, setCurrentView] = useState<string>('home');

  // Simple state-based router
  const renderView = () => {
    if (role === UserRole.GUEST) {
      return <LoginView onLogin={(newRole) => setRole(newRole)} />;
    }

    // Role-specific views
    switch (currentView) {
      case 'home':
        if (role === UserRole.STAFF) return <StaffValidator onBack={() => setRole(UserRole.GUEST)} />;
        if (role === UserRole.ADMIN) return <AdminDashboard onNavigate={(v) => setCurrentView(v)} onLogout={() => setRole(UserRole.GUEST)} />;
        return <CustomerHome onNavigate={(v) => setCurrentView(v)} onLogout={() => setRole(UserRole.GUEST)} />;

      case 'ranking':
        return <Leaderboard onBack={() => setCurrentView('home')} />;

      case 'create-pool':
        return <CreatePool onBack={() => setCurrentView('home')} />;

      case 'analytics':
        return <Analytics onBack={() => setCurrentView('home')} />;

      case 'branding':
        return <BrandCustomization onBack={() => setCurrentView('home')} />;

      default:
        return <CustomerHome onNavigate={(v) => setCurrentView(v)} onLogout={() => setRole(UserRole.GUEST)} />;
    }
  };

  return (
    <div className="min-h-screen max-w-md mx-auto relative bg-background-dark shadow-2xl overflow-hidden flex flex-col">
      {renderView()}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
