    if (pool) {
      setEditingPool(pool);
      setFormData({
        name: pool.name,
        endDate: pool.endDate,
        endTime: pool.endTime,
        prize: pool.prize,
        entry: pool.entry,
        type: pool.type,
        status: pool.status
