        prize: pool.prize,
        entry: pool.entry,
        type: pool.type,
        status: pool.status
      });
    } else {
      setEditingPool(null);
      setFormData({
        name: '',
        endDate: '',
        endTime: '',
        prize: '',
        entry: '',
        type: 'Futebol',
        status: 'pendente'
      });
    }
    setIsModalOpen(true);
  };

  const handleSave = () => {
    if (editingPool) {
      setPools(prev => prev.map(p => p.id === editingPool.id ? { ...p, ...formData } : p));
    } else {
      const newPool: PoolData = {
        id: Math.random().toString(36).substr(2, 9),
        participants: 0,
        ...formData
      };
      setPools(prev => [newPool, ...prev]);
    }
    setIsModalOpen(false);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'ativo': return 'bg-primary/20 text-primary border-primary/30';
      case 'pendente': return 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30';
      case 'finalizado': return 'bg-white/10 text-gray-400 border-white/5';
      default: return '';
    }
  };

  return (
    <div className="flex flex-col min-h-screen bg-background-dark pb-24 lg:pb-12 px-6 lg:px-10">
      <header className="py-8 flex flex-col md:flex-row md:items-center justify-between gap-6 border-b border-white/5 mb-8">
