        <button 
          onClick={() => handleOpenModal()}
          className="h-12 px-6 bg-primary text-background-dark font-black rounded-2xl text-sm flex items-center justify-center gap-2 shadow-lg shadow-primary/20 hover:scale-105 transition-all active:scale-95"
        >
          <span className="material-symbols-outlined">add_circle</span>
          NOVO BOLÃO
        </button>
      </header>

      {/* Filtros e Busca */}
      <div className="flex flex-col lg:flex-row gap-4 mb-8">
        <div className="relative flex-1">
          <span className="material-symbols-outlined absolute left-4 top-1/2 -translate-y-1/2 text-gray-500">search</span>
          <input 
            type="text" 
            placeholder="Buscar por nome do bolão..." 
            className="w-full bg-surface-dark border border-white/10 rounded-2xl py-3.5 pl-12 pr-4 text-sm focus:ring-primary focus:border-primary transition-all text-white"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>

        <div className="flex gap-4">
          {/* Lista Flutuante de Status */}
          <div className="relative group min-w-[160px]">
            <button className="w-full bg-surface-dark border border-white/10 rounded-2xl px-4 py-3.5 text-xs font-black text-white flex items-center justify-between group-hover:border-primary/50 transition-all">
              <span>{statusFilter.toUpperCase()}</span>
              <span className="material-symbols-outlined text-sm">expand_more</span>
            </button>
            <div className="absolute top-full left-0 w-full mt-2 bg-surface-dark border border-white/10 rounded-2xl overflow-hidden hidden group-hover:block z-50 shadow-2xl">
              {['Todos', 'Ativos', 'Pendentes', 'Finalizados'].map((opt) => (
                <button 
                  key={opt}
                  onClick={() => setStatusFilter(opt)}
                  className="w-full text-left px-4 py-3 text-xs font-bold text-gray-400 hover:bg-white/5 hover:text-primary transition-all"
                >
                  {opt.toUpperCase()}
                </button>
              ))}
            </div>
          </div>

          {/* Lista Flutuante de Modalidades */}
          <div className="relative group min-w-[160px]">
            <button className="w-full bg-surface-dark border border-white/10 rounded-2xl px-4 py-3.5 text-xs font-black text-white flex items-center justify-between group-hover:border-primary/50 transition-all">
              <span>{modalityFilter.toUpperCase()}</span>
              <span className="material-symbols-outlined text-sm">expand_more</span>
            </button>
            <div className="absolute top-full left-0 w-full mt-2 bg-surface-dark border border-white/10 rounded-2xl overflow-hidden hidden group-hover:block z-50 shadow-2xl">
              {['Todas', 'Futebol', 'Basquete', 'MMA', 'NFL'].map((opt) => (
                <button 
                  key={opt}
                  onClick={() => setModalityFilter(opt)}
                  className="w-full text-left px-4 py-3 text-xs font-bold text-gray-400 hover:bg-white/5 hover:text-primary transition-all"
                >
                  {opt.toUpperCase()}
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Grid de Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredPools.map((p) => (
          <div key={p.id} className="bg-surface-dark border border-white/5 rounded-[32px] p-6 hover:border-primary/20 transition-all group flex flex-col">
            <div className="flex justify-between items-start mb-4">
              <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest">{p.type}</span>
              <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase border ${getStatusColor(p.status)}`}>
