};

const SummaryCard = ({ label, value, icon, color }: any) => {
  const colorMap: Record<string, string> = {
    primary: 'text-primary',
    blue: 'text-blue-400',
    purple: 'text-purple-400',
  };
  return (
    <div className="bg-surface-dark border border-white/5 p-6 rounded-[24px]">
      <div className="flex justify-between items-center mb-2">
        <span className="material-symbols-outlined text-gray-500">{icon}</span>
        <p className="text-[10px] font-black uppercase text-gray-500 tracking-widest">{label}</p>
      </div>
      <p className={`text-3xl font-black ${colorMap[color]}`}>{value}</p>
    </div>
  );
};

const DropdownFilter = ({ label, options, onSelect }: any) => (
  <div className="relative group min-w-[160px]">
    <button className="w-full bg-surface-dark border border-white/10 rounded-2xl px-4 py-3.5 text-xs font-black text-white flex items-center justify-between group-hover:border-primary/50 transition-all">
      <span>{label.toUpperCase()}</span>
      <span className="material-symbols-outlined text-sm">expand_more</span>
    </button>
    <div className="absolute top-full left-0 w-full mt-2 bg-surface-dark border border-white/10 rounded-2xl overflow-hidden hidden group-hover:block z-50 shadow-2xl">
      {options.map((opt: string) => (
        <button 
          key={opt}
          onClick={() => onSelect(opt)}
          className="w-full text-left px-4 py-3 text-xs font-bold text-gray-400 hover:bg-white/5 hover:text-primary transition-all"
        >
          {opt.toUpperCase()}
        </button>
      ))}
    </div>
  </div>
);

const NavButton = ({ icon, label, active, onClick }: { icon: string, label: string, active?: boolean, onClick: () => void }) => (
  <button className="flex flex-col items-center gap-1 p-2 min-w-[64px]" onClick={onClick}>
    <span className={`material-symbols-outlined text-[28px] ${active ? 'text-primary' : 'text-gray-500'}`}>{icon}</span>
    <span className={`text-[10px] font-black ${active ? 'text-white' : 'text-gray-500'}`}>{label}</span>
  </button>
);

