import React, { useState } from 'react';
import { UserRole } from './types';
import LoginView from './views/LoginView';
import CustomerHome from './views/CustomerHome';
import StaffValidator from './views/StaffValidator';
import AdminDashboard from './views/AdminDashboard';
import CreatePool from './views/CreatePool';
import Leaderboard from './views/Leaderboard';
import Analytics from './views/Analytics';
import BrandCustomization from './views/BrandCustomization';
import GuessesView from './views/GuessesView';
import CouponsView from './views/CouponsView';
import PoolDetailView from './views/PoolDetailView';
import AdminPoolsView from './views/AdminPoolsView';
import AdminCouponsView from './views/AdminCouponsView';
import AdminCustomersView from './views/AdminCustomersView';
import AdminAlertsView from './views/AdminAlertsView';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.GUEST);
  const [currentView, setCurrentView] = useState<string>('home');
  const [selectedPoolId, setSelectedPoolId] = useState<string | null>(null);

  const navigateToPool = (id: string) => {
    setSelectedPoolId(id);
    setCurrentView('pool-detail');
  };

  if (role === UserRole.GUEST) {
    return <LoginView onLogin={(newRole) => setRole(newRole)} />;
  }

  // Sidebar para Desktop
  const Sidebar = () => (
    <aside className="hidden lg:flex flex-col w-64 bg-surface-dark border-r border-white/5 h-screen sticky top-0 p-6">
      <div className="flex items-center gap-3 mb-10">
        <div className="size-10 rounded-full bg-primary flex items-center justify-center text-background-dark transition-colors">
          <span className="material-symbols-outlined font-bold">sports_bar</span>
        </div>
        <h1 className="font-black text-xl tracking-tight">DRAFT<span className="text-primary transition-colors">APP</span></h1>
      </div>

      <nav className="flex-1 space-y-2">
        <NavItem 
          icon="dashboard" 
          label={role === UserRole.ADMIN ? "Dashboard" : "Início"} 
          view="home" 
          active={currentView === 'home'} 
        />
        {role === UserRole.ADMIN && (
          <>
            <NavItem icon="format_list_bulleted" label="Bolões" view="admin-pools" active={currentView === 'admin-pools'} />
            <NavItem icon="local_activity" label="Cupons" view="admin-coupons" active={currentView === 'admin-coupons'} />
            <NavItem icon="group" label="Clientes" view="admin-customers" active={currentView === 'admin-customers'} />
          </>
        )}
        {role === UserRole.CUSTOMER && (
          <>
            <NavItem icon="receipt_long" label="Meus Palpites" view="guesses" active={currentView === 'guesses'} />
            <NavItem icon="leaderboard" label="Ranking Geral" view="ranking" active={currentView === 'ranking'} />
            <NavItem icon="local_activity" label="Meus Cupons" view="coupons" active={currentView === 'coupons'} />
          </>
        )}
        {role === UserRole.ADMIN && (
          <>
            <NavItem icon="bar_chart" label="Análises" view="analytics" active={currentView === 'analytics'} />
            <NavItem icon="settings" label="Marca" view="branding" active={currentView === 'branding'} />
          </>
        )}
      </nav>

      <button onClick={() => setRole(UserRole.GUEST)} className="mt-auto flex items-center gap-3 p-3 rounded-xl hover:bg-red-500/10 text-gray-400 hover:text-red-500 transition-colors">
        <span className="material-symbols-outlined">logout</span>
        <span className="font-bold">Sair</span>
      </button>
    </aside>
  );

  const NavItem = ({ icon, label, view, active }: { icon: string, label: string, view: string, active: boolean }) => (
    <button 
      onClick={() => setCurrentView(view)}
      className={`w-full flex items-center gap-3 p-3 rounded-xl font-bold transition-all ${active ? 'bg-primary text-background-dark shadow-lg shadow-primary/20' : 'text-gray-400 hover:text-white hover:bg-white/5'}`}
    >
      <span className="material-symbols-outlined">{icon}</span>
      <span>{label}</span>
    </button>
  );

  return (
    <div className="min-h-screen bg-background-dark text-white flex flex-col lg:flex-row font-display">
      <Sidebar />
      <main className="flex-1 overflow-y-auto no-scrollbar">
        <div className="max-w-7xl mx-auto">
          {(() => {
            switch (currentView) {
              case 'home':
                if (role === UserRole.STAFF) return <StaffValidator onBack={() => setRole(UserRole.GUEST)} />;
                if (role === UserRole.ADMIN) return <AdminDashboard onNavigate={(v) => setCurrentView(v)} onLogout={() => setRole(UserRole.GUEST)} />;
                return <CustomerHome onNavigate={(v) => setCurrentView(v)} onSelectPool={navigateToPool} onLogout={() => setRole(UserRole.GUEST)} />;
              case 'admin-pools': return <AdminPoolsView onNavigate={(v) => setCurrentView(v)} onBack={() => setCurrentView('home')} />;
              case 'admin-coupons': return <AdminCouponsView onNavigate={(v) => setCurrentView(v)} onBack={() => setCurrentView('home')} />;
              case 'admin-customers': return <AdminCustomersView onNavigate={(v) => setCurrentView(v)} onBack={() => setCurrentView('home')} />;
              case 'admin-alerts': return <AdminAlertsView onBack={() => setCurrentView('home')} />;
              case 'guesses': return <GuessesView onNavigate={(v) => setCurrentView(v)} />;
              case 'ranking': return <Leaderboard onBack={() => setCurrentView('home')} />;
              case 'coupons': return <CouponsView onNavigate={(v) => setCurrentView(v)} />;
              case 'pool-detail': return <PoolDetailView poolId={selectedPoolId} onBack={() => setCurrentView('home')} />;
              case 'create-pool': return <CreatePool onBack={() => setCurrentView('home')} />;
              case 'analytics': return <Analytics onBack={() => setCurrentView('home')} />;
              case 'branding': return <BrandCustomization onBack={() => setCurrentView('home')} />;
              default: return <CustomerHome onNavigate={(v) => setCurrentView(v)} onSelectPool={navigateToPool} onLogout={() => setRole(UserRole.GUEST)} />;
            }
          })()}
        </div>
      </main>
    </div>
  );
};

export default App;

