    document.documentElement.style.setProperty('--secondary', secondaryColor);
  }, [primaryColor, secondaryColor]);

  const toggleNotif = (key: keyof typeof notifs) => {
    setNotifs(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        alert("O arquivo é muito grande! Máximo de 2MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => setLogo(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleSaveAll = () => {
    alert("Configurações salvas permanentemente!");
    onBack();
  };

  const handleReset = () => {
    if (window.confirm("Deseja resetar todas as alterações para os padrões de fábrica?")) {
      setBarInfo(DEFAULTS.barInfo);
      setPrimaryColor(DEFAULTS.primaryColor);
      setSecondaryColor(DEFAULTS.secondaryColor);
      setNotifs(DEFAULTS.notifs);
      setLogo(null);
    }
  };

  const handleAddMember = () => {
    if (!newMember.name) return;
    const member: TeamMemberData = {
      id: Math.random().toString(36).substr(2, 9),
      name: newMember.name,
      role: newMember.role
    };
    setTeam(prev => [...prev, member]);
    setNewMember({ name: '', role: 'Staff' });
    setIsTeamModalOpen(false);
  };

  const handleDeleteMember = (id: string) => {
    if (window.confirm("Remover este membro da equipe?")) {
      setTeam(prev => prev.filter(m => m.id !== id));
    }
  };

  return (
