            <TabButton active={activeTab === 'aparencia'} label="Aparência" onClick={() => setActiveTab('aparencia')} icon="palette" />
            <TabButton active={activeTab === 'notificacoes'} label="Notificações" onClick={() => setActiveTab('notificacoes')} icon="notifications" />
            <TabButton active={activeTab === 'seguranca'} label="Segurança" onClick={() => setActiveTab('seguranca')} icon="shield" />
          </div>
        </div>
      </header>

      {/* Main Content Area */}
      <div className="p-6 lg:p-10 max-w-7xl mx-auto w-full flex-1 pb-48 overflow-visible">
        {activeTab === 'geral' && (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 animate-in fade-in slide-in-from-bottom-4 duration-500 overflow-visible">
