import AdminCouponsView from './views/AdminCouponsView';
import AdminCustomersView from './views/AdminCustomersView';
import AdminAlertsView from './views/AdminAlertsView';
import AdminPoolStatsView from './views/AdminPoolStatsView';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.GUEST);
  const [currentView, setCurrentView] = useState<string>('home');
  const [selectedPoolId, setSelectedPoolId] = useState<string | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(true);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const navigateToPool = (id: string) => {
    setSelectedPoolId(id);
    setCurrentView('pool-detail');
  };

  const navigateToStats = (id: string) => {
    setSelectedPoolId(id);
    setCurrentView('admin-pool-stats');
  };

  if (role === UserRole.GUEST) {
    return <LoginView onLogin={(newRole) => setRole(newRole)} />;
  }

  const Sidebar = () => (
    <aside className="hidden lg:flex flex-col w-64 bg-white dark:bg-surface-dark border-r border-slate-200 dark:border-white/5 h-screen sticky top-0 p-6 shadow-sm">
      <div className="flex items-center gap-3 mb-10">
        <div className="size-10 rounded-full bg-primary flex items-center justify-center text-background-dark transition-colors">
          <span className="material-symbols-outlined font-bold">sports_bar</span>
        </div>
        <h1 className="font-black text-xl tracking-tight text-slate-900 dark:text-white">DRAFT<span className="text-primary transition-colors">APP</span></h1>
      </div>

      <nav className="flex-1 space-y-2">
        <NavItem icon="dashboard" label={role === UserRole.ADMIN ? "Dashboard" : "Início"} view="home" active={currentView === 'home'} />
        {role === UserRole.ADMIN && (
          <>
            <NavItem icon="format_list_bulleted" label="Bolões" view="admin-pools" active={currentView === 'admin-pools'} />
            <NavItem icon="local_activity" label="Cupons" view="admin-coupons" active={currentView === 'admin-coupons'} />
            <NavItem icon="group" label="Clientes" view="admin-customers" active={currentView === 'admin-customers'} />
          </>
        )}
        {role === UserRole.CUSTOMER && (
          <>
            <NavItem icon="receipt_long" label="Meus Palpites" view="guesses" active={currentView === 'guesses'} />
            <NavItem icon="leaderboard" label="Ranking Geral" view="ranking" active={currentView === 'ranking'} />
            <NavItem icon="local_activity" label="Meus Cupons" view="coupons" active={currentView === 'coupons'} />
          </>
        )}
        {role === UserRole.ADMIN && (
          <>
            <NavItem icon="bar_chart" label="Análises" view="analytics" active={currentView === 'analytics'} />
            <NavItem icon="settings" label="Marca" view="branding" active={currentView === 'branding'} />
          </>
        )}
      </nav>

      <button onClick={() => setRole(UserRole.GUEST)} className="mt-auto flex items-center gap-3 p-3 rounded-xl hover:bg-red-500/10 text-slate-400 hover:text-red-500 transition-colors">
        <span className="material-symbols-outlined">logout</span>
        <span className="font-bold">Sair</span>
      </button>
    </aside>
  );

  const NavItem = ({ icon, label, view, active }: { icon: string, label: string, view: string, active: boolean }) => (
    <button 
      onClick={() => setCurrentView(view)}
      className={`w-full flex items-center gap-3 p-3 rounded-xl font-bold transition-all ${active ? 'bg-primary text-background-dark shadow-lg shadow-primary/20' : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-white/5'}`}
    >
      <span className="material-symbols-outlined">{icon}</span>
      <span>{label}</span>
    </button>
  );

  return (
    <div className="min-h-screen bg-background-light dark:bg-background-dark text-slate-900 dark:text-white flex flex-col lg:flex-row font-display transition-colors">
      <Sidebar />
      <main className="flex-1 overflow-y-auto no-scrollbar relative">
        <div className="max-w-7xl mx-auto min-h-full flex flex-col">
          {(() => {
            switch (currentView) {
              case 'home':
                if (role === UserRole.STAFF) return <StaffValidator onBack={() => setRole(UserRole.GUEST)} />;
                if (role === UserRole.ADMIN) return <AdminDashboard onNavigate={(v) => setCurrentView(v)} onLogout={() => setRole(UserRole.GUEST)} toggleTheme={toggleTheme} isDarkMode={isDarkMode} />;
                return <CustomerHome onNavigate={(v) => setCurrentView(v)} onSelectPool={navigateToPool} onLogout={() => setRole(UserRole.GUEST)} />;
              case 'admin-pools': return <AdminPoolsView onNavigate={(v) => setCurrentView(v)} onBack={() => setCurrentView('home')} onViewStats={navigateToStats} />;
              case 'admin-pool-stats': return <AdminPoolStatsView poolId={selectedPoolId} onBack={() => setCurrentView('admin-pools')} />;
              case 'admin-coupons': return <AdminCouponsView onNavigate={(v) => setCurrentView(v)} onBack={() => setCurrentView('home')} />;
              case 'admin-customers': return <AdminCustomersView onNavigate={(v) => setCurrentView(v)} onBack={() => setCurrentView('home')} />;
              case 'admin-alerts': return <AdminAlertsView onBack={() => setCurrentView('home')} />;
              case 'guesses': return <GuessesView onNavigate={(v) => setCurrentView(v)} />;
              case 'ranking': return <Leaderboard onBack={() => setCurrentView('home')} />;
              case 'coupons': return <CouponsView onNavigate={(v) => setCurrentView(v)} />;
              case 'pool-detail': return <PoolDetailView poolId={selectedPoolId} onBack={() => setCurrentView('home')} />;
              case 'create-pool': return <CreatePool onBack={() => setCurrentView('home')} />;
              case 'analytics': return <Analytics onBack={() => setCurrentView('home')} />;
              case 'branding': return <BrandCustomization onBack={() => setCurrentView('home')} />;
              default: return <CustomerHome onNavigate={(v) => setCurrentView(v)} onSelectPool={navigateToPool} onLogout={() => setRole(UserRole.GUEST)} />;
            }
          })()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';

interface BrandCustomizationProps {
  onBack: () => void;
}

type SubPage = 'geral' | 'aparencia' | 'notificacoes' | 'seguranca';

interface TeamMemberData {
  id: string;
  name: string;
  role: 'Admin' | 'Staff';
}

const DEFAULTS = {
  barInfo: {
    name: 'The Winning Post',
    phone: '(11) 98877-6655',
    address: 'Rua dos Esportes, 123 - Jardins, SP',
    description: 'O melhor bar de esportes da região com transmissões ao vivo e prêmios exclusivos.'
  },
  primaryColor: '#13ec5b',
  secondaryColor: '#3b82f6',
  notifs: {
    participants: true,
    coupons: true,
    poolsEnding: true,
    reports: false
  }
};

const BrandCustomization: React.FC<BrandCustomizationProps> = ({ onBack }) => {
  const [activeTab, setActiveTab] = useState<SubPage>('geral');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // States
  const [barInfo, setBarInfo] = useState(DEFAULTS.barInfo);
  const [logo, setLogo] = useState<string | null>(null);
  const [primaryColor, setPrimaryColor] = useState(DEFAULTS.primaryColor);
  const [secondaryColor, setSecondaryColor] = useState(DEFAULTS.secondaryColor);
  const [notifs, setNotifs] = useState(DEFAULTS.notifs);
  const [team, setTeam] = useState<TeamMemberData[]>([
    { id: '1', name: 'João Silva', role: 'Admin' },
    { id: '2', name: 'Maria Souza', role: 'Staff' },
    { id: '3', name: 'Carlos Roberto', role: 'Staff' },
  ]);
  const [isTeamModalOpen, setIsTeamModalOpen] = useState(false);
  const [newMember, setNewMember] = useState({ name: '', role: 'Staff' as 'Admin' | 'Staff' });

  // Cores CSS
  useEffect(() => {
    document.documentElement.style.setProperty('--primary', primaryColor);
    document.documentElement.style.setProperty('--primary-dark', primaryColor + 'cc');
    document.documentElement.style.setProperty('--secondary', secondaryColor);
  }, [primaryColor, secondaryColor]);

  const toggleNotif = (key: keyof typeof notifs) => {
    setNotifs(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        alert("O arquivo é muito grande! Máximo de 2MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => setLogo(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleSaveAll = () => {
    alert("Configurações salvas!");
    onBack();
  };

  const handleReset = () => {
    if (window.confirm("Resetar para os padrões?")) {
      setBarInfo(DEFAULTS.barInfo);
      setPrimaryColor(DEFAULTS.primaryColor);
      setSecondaryColor(DEFAULTS.secondaryColor);
      setNotifs(DEFAULTS.notifs);
      setLogo(null);
    }
  };

  const handleAddMember = () => {
    if (!newMember.name) return;
    const member: TeamMemberData = {
      id: Math.random().toString(36).substr(2, 9),
      name: newMember.name,
      role: newMember.role
    };
    setTeam(prev => [...prev, member]);
    setNewMember({ name: '', role: 'Staff' });
    setIsTeamModalOpen(false);
  };

  const handleDeleteMember = (id: string) => {
    if (window.confirm("Remover este membro?")) {
      setTeam(prev => prev.filter(m => m.id !== id));
    }
  };

  return (
    <div className="flex flex-col min-h-screen bg-background-light dark:bg-background-dark font-display relative">
      <header className="py-8 px-6 lg:px-10 border-b border-slate-200 dark:border-white/5 bg-white/90 dark:bg-background-dark/90 backdrop-blur-xl sticky top-0 z-40 transition-colors">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 max-w-7xl mx-auto w-full">
          <div>
            <h2 className="text-3xl font-black uppercase italic tracking-tight text-slate-900 dark:text-white">Gestão da <span className="text-primary transition-colors">Marca</span></h2>
            <p className="text-sm font-bold text-slate-500 dark:text-gray-500 uppercase tracking-widest mt-1">Personalize a identidade do seu negócio</p>
          </div>

          <div className="flex bg-slate-100 dark:bg-surface-dark p-1 rounded-2xl border border-slate-200 dark:border-white/10 overflow-x-auto no-scrollbar">
            <TabButton active={activeTab === 'geral'} label="Geral" onClick={() => setActiveTab('geral')} icon="info" />
            <TabButton active={activeTab === 'aparencia'} label="Aparência" onClick={() => setActiveTab('aparencia')} icon="palette" />
            <TabButton active={activeTab === 'notificacoes'} label="Notificações" onClick={() => setActiveTab('notificacoes')} icon="notifications" />
            <TabButton active={activeTab === 'seguranca'} label="Segurança" onClick={() => setActiveTab('seguranca')} icon="shield" />
          </div>
        </div>
      </header>

      {/* Container sem overflow hidden para permitir scroll livre */}
      <div className="p-6 lg:p-10 max-w-7xl mx-auto w-full flex-1 pb-48">
        {activeTab === 'geral' && (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <section className="bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/5 rounded-[40px] p-8 shadow-sm h-fit">
              <h3 className="text-xl font-black uppercase italic mb-8 flex items-center gap-2 text-slate-900 dark:text-white">
                <span className="material-symbols-outlined text-primary">storefront</span>
                Informações do <span className="text-primary">Bar</span>
              </h3>
              <div className="space-y-6">
                <InputGroup label="Nome do Bar" value={barInfo.name} onChange={(v: string) => setBarInfo({...barInfo, name: v})} />
                <InputGroup label="Telefone" value={barInfo.phone} onChange={(v: string) => setBarInfo({...barInfo, phone: v})} />
                <InputGroup label="Endereço" value={barInfo.address} onChange={(v: string) => setBarInfo({...barInfo, address: v})} />
                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest mb-2 block">Descrição</label>
                  <textarea 
                    className="w-full bg-slate-50 dark:bg-background-dark border border-slate-200 dark:border-white/10 rounded-2xl p-4 text-sm text-slate-900 dark:text-white focus:ring-primary focus:border-primary transition-all min-h-[120px] resize-none"
                    value={barInfo.description}
                    onChange={(e) => setBarInfo({...barInfo, description: e.target.value})}
                  />
                </div>
              </div>
            </section>

            <section className="bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/5 rounded-[40px] p-8 shadow-sm flex flex-col h-fit">
              <h3 className="text-xl font-black uppercase italic mb-8 flex items-center gap-2 text-slate-900 dark:text-white">
                <span className="material-symbols-outlined text-primary">image</span>
                Logotipo <span className="text-primary">Oficial</span>
              </h3>
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleLogoUpload} />
              <div 
                onClick={() => fileInputRef.current?.click()}
                className="flex-1 flex flex-col items-center justify-center border-2 border-dashed border-slate-200 dark:border-white/10 rounded-[32px] p-10 group hover:border-primary/50 transition-all cursor-pointer bg-slate-50 dark:bg-background-dark/30 min-h-[220px]"
              >
                {logo ? (
                  <img src={logo} alt="Logo preview" className="max-h-32 object-contain mb-4" />
                ) : (
                  <span className="material-symbols-outlined text-5xl text-slate-300 dark:text-gray-600 mb-4 group-hover:text-primary transition-colors">cloud_upload</span>
                )}
                <p className="text-sm font-bold text-slate-400 dark:text-gray-400">{logo ? 'Substituir logotipo' : 'Clique para fazer upload'}</p>
              </div>
              <div className="mt-6 p-4 bg-primary/5 rounded-2xl border border-primary/10 text-slate-900 dark:text-white">
                <p className="text-[10px] font-black text-primary uppercase tracking-widest mb-1 text-center">Preview da Marca</p>
                <div className="flex items-center justify-center gap-4 py-2">
                   <div className="size-12 rounded-full bg-primary flex items-center justify-center text-background-dark overflow-hidden">
                     {logo ? <img src={logo} className="w-full h-full object-cover" /> : <span className="material-symbols-outlined font-bold">sports_bar</span>}
                   </div>
                   <span className="text-xl font-black italic">{barInfo.name}</span>
                </div>
              </div>
            </section>
          </div>
        )}

        {activeTab === 'aparencia' && (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <section className="bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/5 rounded-[40px] p-8 shadow-sm h-fit text-slate-900 dark:text-white">
              <h3 className="text-xl font-black uppercase italic mb-8 flex items-center gap-2">
                <span className="material-symbols-outlined text-primary">palette</span>
                Cores do <span className="text-primary">Tema</span>
              </h3>
              <div className="space-y-8">
                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest mb-4 block">Cor Primária</label>
                  <ColorPicker color={primaryColor} onChange={setPrimaryColor} />
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest mb-4 block">Cor Secundária</label>
                  <ColorPicker color={secondaryColor} onChange={setSecondaryColor} />
                </div>
              </div>
            </section>

            <section className="bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/5 rounded-[40px] p-8 shadow-sm h-fit">
              <h3 className="text-xl font-black uppercase italic mb-8 flex items-center gap-2 text-slate-900 dark:text-white">
                <span className="material-symbols-outlined text-primary">visibility</span>
                Preview <span className="text-primary">Visual</span>
              </h3>
              <div className="relative aspect-video rounded-[32px] bg-slate-100 dark:bg-background-dark border border-slate-200 dark:border-white/5 overflow-hidden p-6">
                <div className="flex flex-col h-full gap-4">
                  <div className="h-12 w-full rounded-2xl bg-white dark:bg-surface-dark flex items-center px-4 gap-3 shadow-sm border border-slate-200 dark:border-transparent">
                    <div className="size-6 rounded-full" style={{backgroundColor: primaryColor}}></div>
                    <div className="h-2 w-24 bg-slate-300 dark:bg-white/10 rounded-full"></div>
                  </div>
                  <div className="flex-1 grid grid-cols-2 gap-4">
                    <div className="rounded-2xl border-2 p-4 flex flex-col justify-end gap-2" style={{borderColor: primaryColor + '33'}}>
                       <div className="h-2 w-16 bg-slate-300 dark:bg-white/10 rounded-full"></div>
                       <div className="h-8 w-full rounded-xl" style={{backgroundColor: primaryColor}}></div>
                    </div>
                  </div>
                </div>
              </div>
            </section>
          </div>
        )}

        {activeTab === 'notificacoes' && (
          <div className="max-w-2xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500">
            <section className="bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/5 rounded-[40px] p-8 shadow-sm text-slate-900 dark:text-white">
              <h3 className="text-xl font-black uppercase italic mb-4 flex items-center gap-2">
                <span className="material-symbols-outlined text-primary">notifications_active</span>
                Preferências
              </h3>
              <div className="space-y-4">
                <NotifToggle active={notifs.participants} label="Novos Participantes" description="Alerta de novos inscritos" onClick={() => toggleNotif('participants')} />
                <NotifToggle active={notifs.coupons} label="Cupons Resgatados" description="Notificação de validação" onClick={() => toggleNotif('coupons')} />
                <NotifToggle active={notifs.poolsEnding} label="Bolões Encerrando" description="Aviso 24h antes" onClick={() => toggleNotif('poolsEnding')} />
              </div>
            </section>
          </div>
        )}

        {activeTab === 'seguranca' && (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <section className="bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/5 rounded-[40px] p-8 shadow-sm h-fit">
              <h3 className="text-xl font-black uppercase italic mb-8 flex items-center gap-2 text-slate-900 dark:text-white">
                <span className="material-symbols-outlined text-primary">lock</span>
                Segurança
              </h3>
              <div className="space-y-6">
                <InputGroup label="Senha Atual" type="password" placeholder="********" />
                <InputGroup label="Nova Senha" type="password" />
                <button className="w-full py-4 bg-primary text-background-dark font-black rounded-2xl shadow-xl hover:scale-[1.02] transition-all">ATUALIZAR SENHA</button>
              </div>
            </section>

            <section className="bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/5 rounded-[40px] p-8 shadow-sm h-fit">
              <div className="flex items-center justify-between mb-8 text-slate-900 dark:text-white">
                <h3 className="text-xl font-black uppercase italic flex items-center gap-2">
                  <span className="material-symbols-outlined text-primary">groups_2</span>
                  Equipe
                </h3>
                <button onClick={() => setIsTeamModalOpen(true)} className="size-10 rounded-xl bg-primary/10 text-primary flex items-center justify-center hover:bg-primary hover:text-background-dark transition-all">
                  <span className="material-symbols-outlined">add</span>
                </button>
              </div>
              <div className="space-y-3">
                {team.map(member => (
                  <TeamMember key={member.id} id={member.id} name={member.name} role={member.role} onDelete={() => handleDeleteMember(member.id)} />
                ))}
              </div>
            </section>
          </div>
        )}
      </div>

      {/* Footer Fixo */}
      <div className="fixed bottom-0 left-0 right-0 p-6 bg-white/80 dark:bg-background-dark/95 backdrop-blur-xl border-t border-slate-200 dark:border-white/5 z-30 lg:left-64 transition-colors">
        <div className="max-w-7xl mx-auto flex gap-4">
          <button onClick={handleReset} className="flex-1 py-4 bg-slate-100 dark:bg-white/5 hover:bg-slate-200 dark:hover:bg-white/10 text-slate-900 dark:text-white font-black rounded-2xl transition-all">
            RESETAR
          </button>
          <button onClick={handleSaveAll} className="flex-1 py-4 bg-primary text-background-dark font-black rounded-2xl shadow-2xl shadow-primary/30 hover:scale-[1.02] transition-all flex items-center justify-center gap-2">
            <span className="material-symbols-outlined font-black">save</span>
            SALVAR ALTERAÇÕES
          </button>
        </div>
      </div>

      {/* Modal Adicionar Equipe */}
      {isTeamModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-background-dark/95 backdrop-blur-md" onClick={() => setIsTeamModalOpen(false)}></div>
          <div className="relative z-10 w-full max-w-md bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/10 rounded-[40px] shadow-2xl animate-in fade-in zoom-in duration-300">
            <div className="p-8 border-b border-slate-200 dark:border-white/5 flex items-center justify-between text-slate-900 dark:text-white">
              <h3 className="text-2xl font-black italic uppercase tracking-tight">Novo <span className="text-primary">Membro</span></h3>
              <button onClick={() => setIsTeamModalOpen(false)} className="size-10 flex items-center justify-center"><span className="material-symbols-outlined">close</span></button>
            </div>
            <div className="p-8 space-y-6">
              <InputGroup label="Nome" value={newMember.name} onChange={v => setNewMember({...newMember, name: v})} />
              <div className="p-8 border-t border-slate-100 dark:border-white/5 flex gap-4">
                <button onClick={() => setIsTeamModalOpen(false)} className="flex-1 py-4 bg-slate-100 dark:bg-white/5 rounded-2xl font-black text-slate-900 dark:text-white">CANCELAR</button>
                <button onClick={handleAddMember} className="flex-1 py-4 bg-primary text-background-dark rounded-2xl font-black shadow-xl shadow-primary/20">ADICIONAR</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const TabButton = ({ active, label, onClick, icon }: any) => (
  <button onClick={onClick} className={`px-6 py-2.5 rounded-xl text-xs font-black transition-all flex items-center gap-2 whitespace-nowrap ${active ? 'bg-primary text-background-dark shadow-xl' : 'text-slate-500 dark:text-gray-500 hover:text-slate-900 dark:hover:text-white'}`}>
    <span className="material-symbols-outlined text-sm">{icon}</span>
    {label.toUpperCase()}
  </button>
);

const InputGroup = ({ label, value, onChange, type = "text", placeholder }: any) => (
  <div>
    <label className="text-[10px] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest mb-2 block">{label}</label>
    <input type={type} className="w-full bg-slate-50 dark:bg-background-dark border border-slate-200 dark:border-white/10 rounded-2xl p-4 text-sm text-slate-900 dark:text-white focus:ring-primary transition-all" value={value} onChange={e => onChange?.(e.target.value)} placeholder={placeholder} />
  </div>
);

const ColorPicker = ({ color, onChange }: any) => {
  const presets = ['#13ec5b', '#3b82f6', '#ef4444', '#fbbf24', '#a855f7'];
  return (
    <div className="flex items-center gap-4">
      <div className="size-14 rounded-2xl border border-slate-200 dark:border-white/10 flex-shrink-0 shadow-lg" style={{backgroundColor: color}}></div>
      <div className="flex flex-wrap gap-2">
