import React, { useState, useMemo } from 'react';

interface CouponData {
  id: string;
  name: string;
  code: string;
  type: 'Desconto' | 'Brinde' | 'Cashback';
  value: string;
  usage: string;
  expiryDate: string;
  status: 'Ativo' | 'Expirado' | 'Esgotado';
}

interface AdminCouponsViewProps {
  onNavigate: (view: string) => void;
  onBack: () => void;
}

const INITIAL_COUPONS: CouponData[] = [
  { id: '1', name: 'Primeira Compra', code: 'WELCOME20', type: 'Desconto', value: '20%', usage: '124/500', expiryDate: '2024-12-31', status: 'Ativo' },
  { id: '2', name: 'Chopp Grátis Quarta', code: 'CHOPP4A', type: 'Brinde', value: '1 Chopp', usage: '45/100', expiryDate: '2024-06-30', status: 'Ativo' },
  { id: '3', name: 'Cashback Especial', code: 'CASH10', type: 'Cashback', value: '10%', usage: '89/100', expiryDate: '2024-05-15', status: 'Expirado' },
  { id: '4', name: 'Aniversário Bar', code: 'ANIVBAR', type: 'Desconto', value: 'R$ 50', usage: '200/200', expiryDate: '2024-12-31', status: 'Esgotado' },
];

const AdminCouponsView: React.FC<AdminCouponsViewProps> = ({ onNavigate, onBack }) => {
  const [coupons, setCoupons] = useState<CouponData[]>(INITIAL_COUPONS);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('Todos');
  const [typeFilter, setTypeFilter] = useState('Todos');

  // Modal states
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingCoupon, setEditingCoupon] = useState<CouponData | null>(null);

  const [formData, setFormData] = useState<Partial<CouponData>>({
    name: '',
    code: '',
    type: 'Desconto',
    value: '',
    expiryDate: '',
    status: 'Ativo'
  });

  const filteredCoupons = useMemo(() => {
    return coupons.filter(c => {
      const matchesSearch = c.name.toLowerCase().includes(search.toLowerCase()) || c.code.toLowerCase().includes(search.toLowerCase());
      const matchesStatus = statusFilter === 'Todos' || c.status === statusFilter;
      const matchesType = typeFilter === 'Todos' || c.type === typeFilter;
      return matchesSearch && matchesStatus && matchesType;
    });
  }, [coupons, search, statusFilter, typeFilter]);

  const stats = {
    emitted: 1250, 
    used: 458,
    rate: '45.8%'
  };

  const handleOpenModal = (coupon?: CouponData) => {
    if (coupon) {
      setEditingCoupon(coupon);
      setFormData(coupon);
    } else {
      setEditingCoupon(null);
      setFormData({
        name: '',
        code: '',
        type: 'Desconto',
        value: '',
        expiryDate: '',
        status: 'Ativo'
      });
    }
    setIsModalOpen(true);
  };

  const handleSave = () => {
    if (editingCoupon) {
      setCoupons(prev => prev.map(c => c.id === editingCoupon.id ? { ...c, ...formData as CouponData } : c));
    } else {
      const newCoupon: CouponData = {
        id: Math.random().toString(36).substr(2, 9),
        usage: '0/100',
        ...formData as CouponData
      };
      setCoupons(prev => [newCoupon, ...prev]);
    }
    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => {
    if (window.confirm('Tem certeza que deseja excluir este cupom? Esta ação não pode ser desfeita.')) {
      setCoupons(prev => prev.filter(c => c.id !== id));
    }
  };

  const formatDate = (dateStr: string) => {
    if (!dateStr) return '-';
    const parts = dateStr.split('-');
    if (parts.length === 3) {
      return `${parts[2]}/${parts[1]}/${parts[0]}`;
    }
    return dateStr;
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Ativo': return 'bg-primary/20 text-primary border-primary/30';
      case 'Expirado': return 'bg-red-500/20 text-red-500 dark:text-red-400 border-red-500/30';
      case 'Esgotado': return 'bg-yellow-500/20 text-yellow-600 dark:text-yellow-400 border-yellow-500/30';
      default: return 'bg-slate-100 dark:bg-white/10 text-slate-500 dark:text-gray-400 border-slate-200 dark:border-white/5';
    }
  };

  return (
    <div className="flex flex-col min-h-screen bg-background-light dark:bg-background-dark pb-24 lg:pb-12 px-6 lg:px-10 transition-colors">
      <header className="py-8 flex flex-col md:flex-row md:items-center justify-between gap-6 border-b border-slate-200 dark:border-white/5 mb-8">
        <div>
          <h2 className="text-3xl font-black uppercase italic tracking-tight text-slate-900 dark:text-white">Gestão de <span className="text-primary">Cupons</span></h2>
          <p className="text-sm font-bold text-slate-500 dark:text-gray-500 uppercase tracking-widest mt-1">Configure recompensas para seus clientes</p>
        </div>
        <button 
          onClick={() => handleOpenModal()}
          className="h-12 px-6 bg-primary text-background-dark font-black rounded-2xl text-sm flex items-center justify-center gap-2 shadow-lg shadow-primary/20 hover:scale-105 transition-all active:scale-95"
        >
          <span className="material-symbols-outlined">local_activity</span>
          NOVO CUPOM
        </button>
      </header>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 mb-10">
        <SummaryCard label="Emitidos" value={stats.emitted} icon="outbox" color="primary" />
        <SummaryCard label="Usados" value={stats.used} icon="check_circle" color="blue" />
        <SummaryCard label="Taxa de Uso" value={stats.rate} icon="analytics" color="purple" />
      </div>

      {/* Filtros e Busca */}
      <div className="flex flex-col lg:flex-row gap-4 mb-8">
        <div className="relative flex-1">
          <span className="material-symbols-outlined absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">search</span>
          <input 
