import CustomerHome from './views/CustomerHome';
import StaffValidator from './views/StaffValidator';
import AdminDashboard from './views/AdminDashboard';
import CreatePool from './views/CreatePool';
import Leaderboard from './views/Leaderboard';
import Analytics from './views/Analytics';
import BrandCustomization from './views/BrandCustomization';
import GuessesView from './views/GuessesView';
import CouponsView from './views/CouponsView';
import PoolDetailView from './views/PoolDetailView';
import AdminPoolsView from './views/AdminPoolsView';
import AdminCouponsView from './views/AdminCouponsView';
import AdminCustomersView from './views/AdminCustomersView';
import AdminAlertsView from './views/AdminAlertsView';
import AdminPoolStatsView from './views/AdminPoolStatsView';
import CareerDetailsView from './views/CareerDetailsView';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.GUEST);
  const [currentView, setCurrentView] = useState<string>('home');
  const [isCustomerAuth, setIsCustomerAuth] = useState(false);
  const [selectedPoolId, setSelectedPoolId] = useState<string | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const navigateToPool = (id: string) => {
    setSelectedPoolId(id);
  };

  const navigateToStats = (id: string) => {
    setSelectedPoolId(id);
    setCurrentView('admin-pool-stats');
  };

  const handleLogin = (newRole: UserRole) => {
    setRole(newRole);
    setIsCustomerAuth(false);
    setCurrentView('home');
    setIsSidebarOpen(false);
  };

  const openSidebar = () => setIsSidebarOpen(true);

  if (role === UserRole.GUEST && !isCustomerAuth) {
    return <LoginView onLogin={handleLogin} onCustomerAuth={() => setIsCustomerAuth(true)} />;
  }

  if (isCustomerAuth) {
    return <CustomerAuthView onLogin={handleLogin} onBack={() => setIsCustomerAuth(false)} />;
  }

  const Sidebar = () => (
    <>
      {/* Overlay para mobile */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[60] lg:hidden"
          onClick={() => setIsSidebarOpen(false)}
        ></div>
      )}

      <aside className={`fixed lg:sticky top-0 left-0 z-[70] flex flex-col w-64 bg-white dark:bg-surface-dark border-r border-slate-200 dark:border-white/5 h-screen p-6 shadow-2xl lg:shadow-sm transition-transform duration-300 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="flex items-center justify-between mb-10">
          <div className="flex items-center gap-3">
            <div className="size-10 rounded-full bg-primary flex items-center justify-center text-background-dark">
              <span className="material-symbols-outlined font-bold">sports_bar</span>
            </div>
            <h1 className="font-black text-xl tracking-tight text-slate-900 dark:text-white">DRAFT<span className="text-primary transition-colors">APP</span></h1>
          </div>
          <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden size-8 flex items-center justify-center rounded-lg bg-slate-100 dark:bg-white/5 text-slate-500">
            <span className="material-symbols-outlined">close</span>
          </button>
        </div>

        <nav className="flex-1 space-y-2">
          <NavItem icon="dashboard" label={(role === UserRole.ADMIN) ? "Dashboard" : "Início"} view="home" active={currentView === 'home'} />
          {role === UserRole.ADMIN && (
            <>
              <NavItem icon="format_list_bulleted" label="Bolões" view="admin-pools" active={currentView === 'admin-pools'} />
              <NavItem icon="local_activity" label="Cupons" view="admin-coupons" active={currentView === 'admin-coupons'} />
              <NavItem icon="group" label="Clientes" view="admin-customers" active={currentView === 'admin-customers'} />
              <NavItem icon="bar_chart" label="Análises" view="analytics" active={currentView === 'analytics'} />
              <NavItem icon="settings" label="Marca" view="branding" active={currentView === 'branding'} />
            </>
          )}
          {role === UserRole.CUSTOMER && (
            <>
              <NavItem icon="receipt_long" label="Meus Palpites" view="guesses" active={currentView === 'guesses'} />
              <NavItem icon="leaderboard" label="Ranking Geral" view="ranking" active={currentView === 'ranking'} />
              <NavItem icon="local_activity" label="Meus Cupons" view="coupons" active={currentView === 'coupons'} />
            </>
          )}
        </nav>

        <div className="mt-auto pt-6 border-t border-slate-100 dark:border-white/5 space-y-2">
          <button 
            onClick={toggleTheme}
            className="w-full flex items-center gap-3 p-3 rounded-xl font-bold text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-white/5 transition-all"
          >
            <span className="material-symbols-outlined">{isDarkMode ? 'light_mode' : 'dark_mode'}</span>
            <span>Modo {isDarkMode ? 'Claro' : 'Escuro'}</span>
          </button>
          <button onClick={() => { handleLogin(UserRole.GUEST); setIsSidebarOpen(false); }} className="w-full flex items-center gap-3 p-3 rounded-xl hover:bg-red-500/10 text-slate-400 hover:text-red-500 transition-colors font-bold">
            <span className="material-symbols-outlined">logout</span>
            <span>Sair</span>
          </button>
        </div>
      </aside>
    </>
  );

  const NavItem = ({ icon, label, view, active }: { icon: string, label: string, view: string, active: boolean }) => (
    <button 
      onClick={() => { setCurrentView(view); setIsSidebarOpen(false); }}
      className={`w-full flex items-center gap-3 p-3 rounded-xl font-bold transition-all ${active ? 'bg-primary text-background-dark shadow-lg shadow-primary/20' : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-white/5'}`}
    >
      <span className="material-symbols-outlined">{icon}</span>
      <span>{label}</span>
    </button>
  );

  return (
    <div className="min-h-screen bg-background-light dark:bg-background-dark text-slate-900 dark:text-white flex flex-col lg:flex-row font-display transition-colors">
      <Sidebar />
      <main className="flex-1 overflow-y-auto no-scrollbar relative">
        <div className="max-w-7xl mx-auto min-h-full flex flex-col">
          {(() => {
            switch (currentView) {
              case 'home':
                if (role === UserRole.STAFF) return <StaffValidator onBack={() => setRole(UserRole.GUEST)} />;
                if (role === UserRole.ADMIN) return <AdminDashboard onNavigate={(v) => setCurrentView(v)} onLogout={() => setRole(UserRole.GUEST)} toggleTheme={toggleTheme} isDarkMode={isDarkMode} openSidebar={openSidebar} />;
                return <CustomerHome openSidebar={openSidebar} onNavigate={(v) => setCurrentView(v)} onSelectPool={navigateToPool} onLogout={() => setRole(UserRole.GUEST)} />;
              case 'admin-pools': return <AdminPoolsView onNavigate={(v) => setCurrentView(v)} onBack={() => setCurrentView('home')} onViewStats={navigateToStats} />;
              case 'admin-pool-stats': return <AdminPoolStatsView poolId={selectedPoolId} onBack={() => setCurrentView('admin-pools')} />;
              case 'admin-coupons': return <AdminCouponsView onNavigate={(v) => setCurrentView(v)} onBack={() => setCurrentView('home')} />;
              case 'admin-customers': return <AdminCustomersView onNavigate={(v) => setCurrentView(v)} onBack={() => setCurrentView('home')} />;
              case 'admin-alerts': return <AdminAlertsView onBack={() => setCurrentView('home')} />;
              case 'guesses': return <GuessesView openSidebar={openSidebar} onNavigate={(v) => setCurrentView(v)} />;
              case 'ranking': return <Leaderboard openSidebar={openSidebar} onNavigate={(v) => setCurrentView(v)} onBack={() => setCurrentView('home')} />;
              case 'career-details': return <CareerDetailsView onBack={() => setCurrentView('ranking')} />;
              case 'coupons': return <CouponsView openSidebar={openSidebar} onNavigate={(v) => setCurrentView(v)} />;
              case 'create-pool': return <CreatePool onBack={() => setCurrentView('home')} />;
              case 'analytics': return <Analytics onBack={() => setCurrentView('home')} />;
              case 'branding': return <BrandCustomization onBack={() => setCurrentView('home')} />;
              default: return <CustomerHome openSidebar={openSidebar} onNavigate={(v) => setCurrentView(v)} onSelectPool={navigateToPool} onLogout={() => setRole(UserRole.GUEST)} />;
            }
          })()}
        </div>

        {/* Pool Detail Popup Rendered over content */}
        {selectedPoolId && (
          <PoolDetailView poolId={selectedPoolId} onBack={() => setSelectedPoolId(null)} />
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';

interface PoolDetailViewProps {
  poolId: string | null;
  onBack: () => void;
}

const PoolDetailView: React.FC<PoolDetailViewProps> = ({ poolId, onBack }) => {
  const [scores, setScores] = useState({ home: '', away: '' });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  const handleConfirm = () => {
    setIsSubmitting(true);
    setTimeout(() => {
      setIsSubmitting(false);
      setIsSuccess(true);
      setTimeout(() => {
        onBack();
      }, 1500);
    }, 1000);
  };

  // Habilitado se qualquer um dos campos de placar estiver preenchido
  const canConfirm = scores.home !== '' || scores.away !== '';

  if (!poolId) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 lg:p-6">
      <div className="absolute inset-0 bg-background-dark/80 backdrop-blur-md" onClick={onBack}></div>

      <div className="relative z-10 w-full max-w-2xl bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/10 rounded-[40px] shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-300">
        <div className="relative h-40 lg:h-56 w-full">
          <img src="https://lh3.googleusercontent.com/aida-public/AB6AXuCQG9hsKNWs-CYKwj5NEMbDLVDsFYXC-Nxt3sGY5Zy3ZWArm7ic7i4dBAUoSeXBH9hmpNByLCUhfEPbBfXizjRorvU9oIZY1WH_REs8jV6rqXorgU2lI8Efja7lG3av1WF52tu9IqCPiobV_ygzPyvGPvFMA6_FlJBuRsz6Su7EYVGutW4dMFSCQuxmMhl5Wl1rT2SpP_wDuR_5t1cprcYGwq6tmpf_jYEp4LPd6oatz0xnDv6-MXZeK7WkjJ5MAFV5P7f6EhOpuA0" className="w-full h-full object-cover" alt="Match" />
          <div className="absolute inset-0 bg-gradient-to-t from-white dark:from-surface-dark via-transparent to-transparent"></div>
          <button onClick={onBack} className="absolute top-6 right-6 size-10 flex items-center justify-center rounded-xl bg-black/50 text-white backdrop-blur-md hover:bg-black/70 transition-all">
            <span className="material-symbols-outlined">close</span>
          </button>
        </div>

        <div className="px-6 lg:px-10 pb-10 -mt-6 relative z-10 space-y-6">
          {isSuccess ? (
            <div className="py-12 flex flex-col items-center animate-in fade-in slide-in-from-bottom-4">
              <div className="size-20 rounded-full bg-primary/20 flex items-center justify-center mb-4">
                <span className="material-symbols-outlined text-primary text-5xl">check_circle</span>
              </div>
              <h2 className="text-2xl font-black italic uppercase text-slate-900 dark:text-white">Palpite Enviado!</h2>
              <p className="text-slate-500 dark:text-gray-400 font-bold uppercase text-xs mt-2 tracking-widest">Boa sorte no jogo!</p>
            </div>
          ) : (
            <>
              <div className="text-center">
                <p className="text-primary font-black text-[10px] uppercase tracking-widest mb-1 italic">Copa América • Ao Vivo</p>
                <h1 className="text-2xl lg:text-3xl font-black italic text-slate-900 dark:text-white uppercase leading-tight">BRASIL vs ARGENTINA</h1>
              </div>

              <div className="space-y-6">
                <h3 className="text-center text-[10px] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest italic">INSIRA O PLACAR FINAL</h3>

                <div className="grid grid-cols-2 gap-4 lg:gap-8">
                  <div className="flex flex-col items-center gap-4">
                    <div className="w-full flex flex-col items-center gap-3 p-4 rounded-3xl border-2 border-slate-100 dark:border-white/5 bg-slate-50 dark:bg-background-dark/50 transition-all">
                      <div className="size-14 rounded-full bg-green-600 flex items-center justify-center font-black text-lg border-4 border-white/20 text-white">BRA</div>
                      <span className="font-black text-sm italic text-slate-900 dark:text-white">BRASIL</span>
                    </div>
                    <input 
                      type="number" 
                      placeholder="0"
                      className="w-20 lg:w-24 text-center bg-slate-50 dark:bg-background-dark border-2 border-slate-200 dark:border-white/10 rounded-2xl p-4 text-2xl font-black text-slate-900 dark:text-white focus:border-primary focus:ring-0 transition-all"
                      value={scores.home}
                      onChange={e => setScores({...scores, home: e.target.value})}
                    />
                  </div>

                  <div className="flex flex-col items-center gap-4">
                    <div className="w-full flex flex-col items-center gap-3 p-4 rounded-3xl border-2 border-slate-100 dark:border-white/5 bg-slate-50 dark:bg-background-dark/50 transition-all">
                      <div className="size-14 rounded-full bg-blue-600 flex items-center justify-center font-black text-lg border-4 border-white/20 text-white">ARG</div>
                      <span className="font-black text-sm italic text-slate-900 dark:text-white">ARGENTINA</span>
                    </div>
                    <input 
                      type="number" 
                      placeholder="0"
                      className="w-20 lg:w-24 text-center bg-slate-50 dark:bg-background-dark border-2 border-slate-200 dark:border-white/10 rounded-2xl p-4 text-2xl font-black text-slate-900 dark:text-white focus:border-primary focus:ring-0 transition-all"
                      value={scores.away}
                      onChange={e => setScores({...scores, away: e.target.value})}
                    />
                  </div>
                </div>
              </div>

              <div className="pt-4">
                <button 
                  disabled={!canConfirm || isSubmitting}
                  onClick={handleConfirm}
                  className={`w-full py-5 rounded-2xl font-black text-lg transition-all shadow-xl flex items-center justify-center gap-2 italic ${canConfirm ? 'bg-primary text-background-dark shadow-primary/30 hover:scale-[1.02]' : 'bg-slate-200 dark:bg-gray-800 text-slate-400 dark:text-gray-500 cursor-not-allowed'}`}
                >
                  {isSubmitting ? (
                    <span className="material-symbols-outlined animate-spin">sync</span>
                  ) : (
                    <>CONFIRMAR PALPITE <span className="material-symbols-outlined font-black">check_circle</span></>
                  )}
                </button>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default PoolDetailView;

import React, { useState } from 'react';

interface GuessesViewProps {
  onNavigate: (view: string) => void;
  openSidebar: () => void;
}

const GuessesView: React.FC<GuessesViewProps> = ({ onNavigate, openSidebar }) => {
  const [guesses, setGuesses] = useState([
    { id: 1, match: 'BRA vs ARG', pick: 'Brasil', score: '2 x 1', status: 'Ganhando', color: 'text-primary' },
    { id: 2, match: 'LAL vs GSW', pick: 'Lakers', score: '102 x 98', status: 'Pendente', color: 'text-yellow-500' },
    { id: 3, match: 'MCI vs INT', pick: 'Man City', score: '1 x 0', status: 'Finalizado', color: 'text-gray-500' },
  ]);

  const handleDelete = (id: number) => {
    if (confirm("Deseja realmente excluir este palpite?")) {
      setGuesses(prev => prev.filter(g => g.id !== id));
    }
  };

  const handleEdit = (id: number) => {
    alert(`Editando palpite #${id}. Uma tela de edição seria aberta aqui.`);
  };

  return (
    <div className="flex flex-col min-h-screen bg-background-light dark:bg-background-dark pb-12 transition-colors">
      <header className="p-4 lg:p-8 pt-8 flex items-center gap-4 border-b border-slate-200 dark:border-white/5 mb-6">
        <button onClick={openSidebar} className="lg:hidden size-10 flex items-center justify-center rounded-xl bg-slate-100 dark:bg-white/5 text-slate-900 dark:text-white">
          <span className="material-symbols-outlined">menu</span>
        </button>
        <div>
          <h1 className="text-2xl lg:text-3xl font-black uppercase italic text-slate-900 dark:text-white leading-none">Meus <span className="text-primary">Palpites</span></h1>
          <p className="text-slate-500 dark:text-gray-400 text-xs font-black uppercase tracking-widest mt-1 italic">Histórico de apostas</p>
        </div>
      </header>

      <div className="flex-1 px-4 lg:px-8 space-y-4">
        {guesses.map((g) => (
          <div key={g.id} className="bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/10 p-5 lg:p-6 rounded-[32px] flex items-center justify-between shadow-sm group hover:border-primary/20 transition-all">
            <div className="flex items-center gap-4">
              <div className="size-12 rounded-2xl bg-slate-50 dark:bg-background-dark flex items-center justify-center text-primary font-black italic">
                {g.pick.substring(0, 3).toUpperCase()}
              </div>
              <div>
                <p className="text-[10px] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest italic">{g.match}</p>
                <p className="text-lg font-black text-slate-900 dark:text-white italic">Palpite: {g.pick} <span className="text-primary ml-2">({g.score})</span></p>
                <div className="flex items-center gap-1.5 mt-1">
                  <div className={`size-2 rounded-full bg-current ${g.color}`}></div>
                  <span className={`text-[10px] font-black uppercase italic ${g.color}`}>{g.status}</span>
                </div>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <button 
                onClick={() => handleEdit(g.id)}
                className="size-10 rounded-xl bg-slate-50 dark:bg-white/5 flex items-center justify-center text-slate-400 hover:text-primary hover:bg-primary/10 transition-all"
              >
                <span className="material-symbols-outlined text-lg">edit</span>
              </button>
              <button 
                onClick={() => handleDelete(g.id)}
                className="size-10 rounded-xl bg-slate-50 dark:bg-white/5 flex items-center justify-center text-slate-400 hover:text-red-500 hover:bg-red-500/10 transition-all"
              >
                <span className="material-symbols-outlined text-lg">delete</span>
              </button>
              <div className="w-4"></div>
              <span className="material-symbols-outlined text-slate-300 dark:text-white/20 group-hover:text-primary transition-all">chevron_right</span>
            </div>
          </div>
        ))}

        {guesses.length === 0 && (
          <div className="flex flex-col items-center justify-center py-20 opacity-30 text-slate-500 animate-in fade-in">
            <span className="material-symbols-outlined text-6xl mb-2">history</span>
            <p className="font-black italic uppercase tracking-widest">Ainda sem palpites.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default GuessesView;

import React, { useState, useEffect } from 'react';
import { UserRole } from './types';
import LoginView from './views/LoginView';
import CustomerAuthView from './views/CustomerAuthView';
import CustomerHome from './views/CustomerHome';
import StaffValidator from './views/StaffValidator';
import AdminDashboard from './views/AdminDashboard';
import CreatePool from './views/CreatePool';
import Leaderboard from './views/Leaderboard';
import Analytics from './views/Analytics';
import BrandCustomization from './views/BrandCustomization';
import GuessesView from './views/GuessesView';
import CouponsView from './views/CouponsView';
import PoolDetailView from './views/PoolDetailView';
import AdminPoolsView from './views/AdminPoolsView';
import AdminCouponsView from './views/AdminCouponsView';
import AdminCustomersView from './views/AdminCustomersView';
import AdminAlertsView from './views/AdminAlertsView';
import AdminPoolStatsView from './views/AdminPoolStatsView';
import CareerDetailsView from './views/CareerDetailsView';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.GUEST);
