  // Estados Globais de Branding
  const [adminName, setAdminName] = useState('João Silva');
  const [adminLogo, setAdminLogo] = useState('https://lh3.googleusercontent.com/aida-public/AB6AXuD1vudwLuyKQjX3PxRhp94tiIr8vczN4GMFbaRGk58KZI8AUnqbWStMuw0IllzoWVlWRB1zUowKGFX8RBUG6JfmeComfRkBBzwEscMmU3SOqXSC7fyDRUSi_qfq-w-nfhqb87y3pCZ8RPMYEiAPD5OCG1O6oOWIyj4JNT0Xk2ofGWpLOyyv9uwbCKj30KYfGy9iV9cCKZfR0d0rgOQRRzwyHuyKMMpoJ4k06JqlDdVAHnlvRvpmWte9Ai7xaWtMkwNim8mMmRYbZuc');

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const navigateToPool = (id: string) => {
    setSelectedPoolId(id);
  };

  const navigateToStats = (id: string) => {
    setSelectedPoolId(id);
    setCurrentView('admin-pool-stats');
  };

  const handleLogin = (newRole: UserRole) => {
    setRole(newRole);
    setIsCustomerAuth(false);
    setCurrentView('home');
    setIsSidebarOpen(false);
  };

  const openSidebar = () => setIsSidebarOpen(true);

  if (role === UserRole.GUEST && !isCustomerAuth) {
    return <LoginView onLogin={handleLogin} onCustomerAuth={() => setIsCustomerAuth(true)} />;
  }

  if (isCustomerAuth) {
    return <CustomerAuthView onLogin={handleLogin} onBack={() => setIsCustomerAuth(false)} />;
