    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        alert("O arquivo é muito grande! Máximo de 2MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setAdminLogo(reader.result as string); // Atualiza globalmente
