import React, { useState, useRef, useEffect } from 'react';

interface StaffValidatorProps {
  onBack: () => void;
}

const StaffValidator: React.FC<StaffValidatorProps> = ({ onBack }) => {
  const [code, setCode] = useState('');
  const [isScanning, setIsScanning] = useState(false);
  const [isFlashOn, setIsFlashOn] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const startCamera = async () => {
    try {
      setIsScanning(true);
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment' },
        audio: false 
      });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
    } catch (err) {
      console.error("Erro ao acessar a câmera:", err);
      alert("Não foi possível acessar a câmera. Verifique as permissões.");
      setIsScanning(false);
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    setIsScanning(false);
  };

  const toggleFlash = async () => {
    if (!streamRef.current) return;
    const track = streamRef.current.getVideoTracks()[0];
    const capabilities = (track as any).getCapabilities?.();

    if (capabilities?.torch) {
      try {
        await (track as any).applyConstraints({
          advanced: [{ torch: !isFlashOn }]
        });
        setIsFlashOn(!isFlashOn);
      } catch (e) {
        console.error("Torch não suportado neste dispositivo", e);
      }
    } else {
      alert("Flash não suportado neste dispositivo/navegador.");
    }
  };

  useEffect(() => {
    startCamera();
    return () => stopCamera();
  }, []);

  return (
    <div className="relative flex flex-col h-full bg-background-dark overflow-hidden font-display">
      <div className="absolute inset-0 z-0 bg-black">
        {isScanning ? (
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            className="h-full w-full object-cover opacity-80"
          />
        ) : (
          <img className="h-full w-full object-cover opacity-60" src="https://lh3.googleusercontent.com/aida-public/AB6AXuD1XhYDZLFaLbUB8aD_tFMh1N5OUnCTAiWzZBA1jO2LjiZLDfgspMl6n-ihxGSmJEUu4V1FPo97mXsGRorpPczmV0p8AQNIHWHd4uYS4RQTC1Tlg7LSgl45KveGhuaBXq58DBOalUmbKMawnWjazr96LJ_Bx6MYKIxeUrNpDko8n6sMBKvfrgMzTr3wqj02tTamD0yePQyM_UyIjGJd0VBCF0V0ikWqr7WqDMKoPzBAiMN_6mk3fFQRj_eaXrE9Pd8GUU9rz6DbqHA" alt="Bar" />
        )}
        <div className="absolute inset-0 bg-gradient-to-b from-black/60 via-transparent to-background-dark"></div>
      </div>

      <header className="relative z-20 flex items-center justify-between p-4 pt-8">
        <div className="flex items-center gap-3">
          <div className="flex h-10 w-10 items-center justify-center rounded-full bg-surface-dark border border-white/10 backdrop-blur-md">
            <span className="material-symbols-outlined text-primary">sports_bar</span>
          </div>
          <div>
            <h1 className="text-xs font-bold text-white/70 uppercase tracking-wider leading-none mb-1">Golden Pint</h1>
            <h2 className="text-lg font-bold text-white leading-none">Validador</h2>
          </div>
        </div>
        <button onClick={onBack} className="flex h-10 w-10 items-center justify-center rounded-full bg-white/10 text-white backdrop-blur-md">
          <span className="material-symbols-outlined">logout</span>
        </button>
      </header>

      <div className="relative z-10 flex flex-1 flex-col items-center justify-center px-6 -mt-10">
        <p className="mb-8 inline-flex items-center gap-2 rounded-full bg-black/60 px-4 py-2 text-sm font-medium text-white border border-white/10">
          <span className="material-symbols-outlined text-primary text-sm">qr_code_scanner</span>
          {isScanning ? "Escaneando código..." : "Aponte para o cupom"}
        </p>

        <div className="relative h-64 w-64 border-2 border-primary/20 rounded-xl overflow-hidden">
          <div className="absolute top-0 left-0 w-8 h-8 border-l-4 border-t-4 border-primary rounded-tl-xl z-20"></div>
          <div className="absolute top-0 right-0 w-8 h-8 border-r-4 border-t-4 border-primary rounded-tr-xl z-20"></div>
          <div className="absolute bottom-0 left-0 w-8 h-8 border-l-4 border-b-4 border-primary rounded-bl-xl z-20"></div>
          <div className="absolute bottom-0 right-0 w-8 h-8 border-r-4 border-b-4 border-primary rounded-br-xl z-20"></div>

          <div className="scan-line absolute h-12 w-full opacity-50 blur-sm z-10"></div>
          <div className="absolute inset-0 flex items-center justify-center opacity-30">
            <span className="material-symbols-outlined text-white text-5xl">add</span>
          </div>
        </div>

        <button 
          onClick={toggleFlash}
          className={`mt-8 flex items-center gap-2 rounded-full px-6 py-3 text-white border transition-all ${isFlashOn ? 'bg-primary text-background-dark border-primary' : 'bg-black/50 border-white/10'}`}
        >
          <span className="material-symbols-outlined">{isFlashOn ? 'flash_off' : 'flash_on'}</span>
          <span className="text-sm font-bold">{isFlashOn ? 'Desligar Flash' : 'Lanterna'}</span>
        </button>
      </div>

      <div className="relative z-20 flex w-full flex-col bg-background-dark rounded-t-3xl border-t border-white/10 pb-8">
        <div className="mx-auto mt-3 h-1.5 w-12 rounded-full bg-white/20"></div>
        <div className="p-6">
          <h3 className="text-xl font-bold text-white mb-4 italic uppercase">Entrada Manual</h3>
          <div className="relative mb-4">
            <span className="material-symbols-outlined absolute left-4 top-5 text-white/40">keyboard</span>
            <input 
              className="h-16 w-full rounded-2xl bg-surface-dark border-none pl-12 pr-4 text-white focus:ring-2 focus:ring-primary uppercase font-bold italic" 
