  useEffect(() => {
    // Definimos a URL baseada na imagem enviada pelo usuário
    setAdminLogo('https://img.freepik.com/premium-photo/neon-sign-bar-play-with-glass-beer-dart-board-it_1102497-210191.jpg?w=1380');
  }, []);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  // Atualiza as cores do tema globalmente
  useEffect(() => {
    document.documentElement.style.setProperty('--primary', primaryColor);
    document.documentElement.style.setProperty('--primary-dark', primaryColor + 'cc');
    document.documentElement.style.setProperty('--secondary', secondaryColor);
