import React, { useState, useMemo } from 'react';

interface PoolData {
  id: string;
  name: string;
  status: 'ativo' | 'pendente' | 'finalizado';
  participants: number;
  endDate: string;
  endTime: string;
  prize: string;
  entry: string;
  type: string;
}

interface AdminPoolsViewProps {
  onNavigate: (view: string) => void;
  onBack: () => void;
  onViewStats: (id: string) => void;
}

const INITIAL_POOLS: PoolData[] = [
  { id: '1', name: 'Final da Champions', status: 'ativo', participants: 45, endDate: '2024-06-01', endTime: '16:00', prize: 'R$ 500,00', entry: 'R$ 20,00', type: 'Futebol' },
  { id: '2', name: 'NBA Finals - G1', status: 'pendente', participants: 12, endDate: '2024-06-05', endTime: '21:00', prize: 'Balde de Spaten', entry: 'Grátis*', type: 'Basquete' },
  { id: '3', name: 'UFC 302: Makhachev vs Poirier', status: 'finalizado', participants: 89, endDate: '2024-05-28', endTime: '23:00', prize: 'Rodízio de Chopp', entry: 'R$ 15,00', type: 'MMA' },
  { id: '4', name: 'Super Bowl LVIII', status: 'finalizado', participants: 156, endDate: '2024-02-11', endTime: '20:30', prize: 'TV 55"', entry: 'R$ 50,00', type: 'NFL' },
];

const AdminPoolsView: React.FC<AdminPoolsViewProps> = ({ onNavigate, onBack, onViewStats }) => {
  const [pools, setPools] = useState<PoolData[]>(INITIAL_POOLS);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('Todos');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingPool, setEditingPool] = useState<PoolData | null>(null);

  const [formData, setFormData] = useState<{
    name: string;
    endDate: string;
    endTime: string;
    prize: string;
    entry: string;
    type: string;
    status: PoolData['status'];
  }>({
    name: '',
    endDate: '',
    endTime: '',
    prize: '',
    entry: '',
    type: 'Futebol',
    status: 'pendente'
  });

  const filteredPools = useMemo(() => {
    return pools.filter(p => {
      const matchesSearch = p.name.toLowerCase().includes(search.toLowerCase());
      let normalizedStatus = statusFilter.toLowerCase();
      if (normalizedStatus === 'ativos') normalizedStatus = 'ativo';
      if (normalizedStatus === 'pendentes') normalizedStatus = 'pendente';
      if (normalizedStatus === 'finalizados') normalizedStatus = 'finalizado';

      const isStatusMatch = statusFilter === 'Todos' || p.status === normalizedStatus;
      return matchesSearch && isStatusMatch;
    });
  }, [pools, search, statusFilter]);

  const handleOpenModal = (pool?: PoolData) => {
    if (pool) {
      setEditingPool(pool);
      setFormData({
        name: pool.name,
        endDate: pool.endDate,
        endTime: pool.endTime,
        prize: pool.prize,
        entry: pool.entry,
        type: pool.type,
        status: pool.status
      });
    } else {
      setEditingPool(null);
      setFormData({ name: '', endDate: '', endTime: '', prize: '', entry: '', type: 'Futebol', status: 'pendente' });
    }
    setIsModalOpen(true);
  };

  const handleSave = () => {
    if (editingPool) {
      setPools(prev => prev.map(p => p.id === editingPool.id ? { ...p, ...formData } : p));
    } else {
      setPools(prev => [{ id: Math.random().toString(36).substr(2, 9), participants: 0, ...formData }, ...prev]);
    }
    setIsModalOpen(false);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'ativo': return 'bg-primary/20 text-primary border-primary/30';
      case 'pendente': return 'bg-yellow-500/20 text-yellow-600 dark:text-yellow-400 border-yellow-500/30';
      case 'finalizado': return 'bg-slate-100 dark:bg-white/10 text-slate-500 dark:text-gray-400 border-slate-200 dark:border-white/5';
      default: return '';
    }
  };

  return (
    <div className="flex flex-col min-h-screen bg-background-light dark:bg-background-dark pb-24 lg:pb-12 px-6 lg:px-10 transition-colors">
      <header className="py-8 flex flex-col md:flex-row md:items-center justify-between gap-6 border-b border-slate-200 dark:border-white/5 mb-8">
        <div>
          <h2 className="text-3xl font-black uppercase tracking-tight text-slate-900 dark:text-white">Gestão de <span className="text-primary">Bolões</span></h2>
          <p className="text-sm font-bold text-slate-500 dark:text-gray-500 uppercase tracking-widest mt-1">Controle e monitore todos os eventos</p>
        </div>
        <button onClick={() => handleOpenModal()} className="h-12 px-6 bg-primary text-background-dark font-black rounded-2xl text-sm flex items-center justify-center gap-2 shadow-lg shadow-primary/20 hover:scale-105 transition-all">
          <span className="material-symbols-outlined">add_circle</span> NOVO BOLÃO
        </button>
      </header>

      <div className="flex flex-col lg:flex-row gap-4 mb-8">
        <div className="relative flex-1">
          <span className="material-symbols-outlined absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">search</span>
          <input type="text" placeholder="Buscar bolão por nome..." className="w-full bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/10 rounded-2xl py-3.5 pl-12 pr-4 text-sm text-slate-900 dark:text-white focus:ring-primary shadow-sm transition-all" value={search} onChange={(e) => setSearch(e.target.value)} />
        </div>
        <div className="flex gap-4">
          <DropdownFilter label={statusFilter} options={['Todos', 'Ativos', 'Pendentes', 'Finalizados']} onSelect={setStatusFilter} />
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredPools.map((p) => (
          <div key={p.id} className="bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/5 rounded-[32px] p-6 hover:border-primary/20 transition-all group flex flex-col shadow-sm">
            <div className="flex justify-between items-start mb-4">
              <span className="text-[10px] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest">{p.type}</span>
              <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase border ${getStatusColor(p.status)} transition-colors`}>
                {p.status}
              </span>
            </div>

            <h3 className="text-xl font-black mb-6 text-slate-900 dark:text-white group-hover:text-primary transition-colors h-12">{p.name}</h3>

            <div className="h-px w-full bg-slate-100 dark:bg-white/5 mb-4"></div>

            <div className="space-y-4 flex-1">
              <div className="flex items-center justify-between">
                <span className="text-xs font-bold text-slate-400 dark:text-gray-400 uppercase tracking-tighter">Participantes</span>
                <span className="text-sm font-black text-slate-900 dark:text-white">{p.participants}</span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-xs font-bold text-slate-400 dark:text-gray-400 uppercase tracking-tighter">Prêmio</span>
                <span className="text-sm font-black text-primary transition-colors">{p.prize}</span>
              </div>
            </div>

            <div className="h-px w-full bg-slate-100 dark:bg-white/5 mt-6 mb-4"></div>

            <div className="flex gap-3">
               <button onClick={() => handleOpenModal(p)} className="flex-1 py-3 bg-slate-100 dark:bg-white/5 hover:bg-slate-200 dark:hover:bg-white/10 rounded-xl text-[10px] font-black text-slate-600 dark:text-white transition-all">EDITAR</button>
               <button onClick={() => onViewStats(p.id)} className="flex-1 py-3 bg-primary/10 hover:bg-primary/20 text-primary rounded-xl text-[10px] font-black transition-all">VER DADOS</button>
            </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-background-dark/95 backdrop-blur-md" onClick={() => setIsModalOpen(false)}></div>
          <div className="relative z-10 w-full max-w-xl bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/10 rounded-[40px] shadow-2xl animate-in fade-in zoom-in duration-300">
             <div className="p-8 border-b border-slate-200 dark:border-white/5 flex items-center justify-between text-slate-900 dark:text-white">
                <h3 className="text-2xl font-black uppercase">{editingPool ? 'Editar' : 'Novo'} Bolão</h3>
                <button onClick={() => setIsModalOpen(false)} className="material-symbols-outlined">close</button>
             </div>
             <div className="p-8 space-y-4 overflow-y-auto max-h-[70vh] no-scrollbar">
                <InputGroup label="Nome" value={formData.name} onChange={v => setFormData({...formData, name: v})} />
                <div className="grid grid-cols-2 gap-4">
                  <InputGroup label="Prêmio" value={formData.prize} onChange={v => setFormData({...formData, prize: v})} />
                  <InputGroup label="Entrada" value={formData.entry} onChange={v => setFormData({...formData, entry: v})} />
                </div>
                <div className="grid grid-cols-2 gap-4">
                   <div>
                     <label className="text-xs font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest mb-2 block">Status</label>
                     <select className="w-full bg-slate-50 dark:bg-background-dark border border-slate-200 dark:border-white/10 rounded-2xl p-4 text-sm text-slate-900 dark:text-white" value={formData.status} onChange={e => setFormData({...formData, status: e.target.value as any})}>
                       <option value="pendente">Pendente</option>
                       <option value="ativo">Ativo</option>
                       <option value="finalizado">Finalizado</option>
                     </select>
                   </div>
                   <div>
                     <label className="text-xs font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest mb-2 block">Modalidade</label>
                     <select className="w-full bg-slate-50 dark:bg-background-dark border border-slate-200 dark:border-white/10 rounded-2xl p-4 text-sm text-slate-900 dark:text-white" value={formData.type} onChange={e => setFormData({...formData, type: e.target.value})}>
                       <option>Futebol</option><option>Basquete</option><option>MMA</option><option>NFL</option>
                     </select>
                   </div>
                </div>
             </div>
             <div className="p-8 border-t border-slate-200 dark:border-white/5 flex gap-4">
                <button onClick={() => setIsModalOpen(false)} className="flex-1 py-4 bg-slate-50 dark:bg-white/5 rounded-2xl font-black text-slate-900 dark:text-white">CANCELAR</button>
                <button onClick={handleSave} className="flex-1 py-4 bg-primary text-background-dark rounded-2xl font-black shadow-xl">SALVAR</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

const InputGroup = ({ label, value, onChange }: any) => (
  <div>
    <label className="text-[10px] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest mb-2 block">{label}</label>
    <input className="w-full bg-slate-50 dark:bg-background-dark border border-slate-200 dark:border-white/10 rounded-2xl p-4 text-sm text-slate-900 dark:text-white" value={value} onChange={e => onChange(e.target.value)} />
  </div>
);

const DropdownFilter = ({ label, options, onSelect }: any) => (
  <div className="relative group min-w-[160px]">
    <button className="w-full bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/10 rounded-2xl px-4 py-3.5 text-xs font-black text-slate-900 dark:text-white flex items-center justify-between group-hover:border-primary shadow-sm transition-all uppercase">
      <span>{label}</span>
      <span className="material-symbols-outlined text-sm">expand_more</span>
    </button>
    <div className="absolute top-full left-0 w-full mt-2 bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/10 rounded-2xl overflow-hidden hidden group-hover:block z-50 shadow-2xl">
      {options.map((opt: string) => (
        <button key={opt} onClick={() => onSelect(opt)} className="w-full text-left px-4 py-3 text-xs font-bold text-slate-600 dark:text-gray-400 hover:bg-primary/10 hover:text-primary transition-all uppercase">{opt}</button>
      ))}
    </div>
  </div>
);

