                  <option value="Staff">Staff (Validador)</option>
                  <option value="Admin">Administrador (Total)</option>
                </select>
              </div>
            </div>
            <div className="p-8 border-t border-slate-100 dark:border-white/5 flex gap-4">
              <button onClick={() => setIsTeamModalOpen(false)} className="flex-1 py-4 bg-slate-100 dark:bg-white/5 rounded-2xl font-black text-slate-900 dark:text-white">CANCELAR</button>
              <button onClick={handleAddMember} className="flex-1 py-4 bg-primary text-background-dark rounded-2xl font-black shadow-xl shadow-primary/20">ADICIONAR</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const TabButton = ({ active, label, onClick, icon }: any) => (
  <button onClick={onClick} className={`px-6 py-2.5 rounded-xl text-xs font-black transition-all flex items-center gap-2 whitespace-nowrap ${active ? 'bg-primary text-background-dark shadow-xl' : 'text-slate-500 dark:text-gray-500 hover:text-slate-900 dark:hover:text-white'}`}>
    <span className="material-symbols-outlined text-sm">{icon}</span>
    {label.toUpperCase()}
  </button>
);

const InputGroup = ({ label, value, onChange, type = "text", placeholder }: any) => (
  <div>
    <label className="text-[10px] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest mb-2 block">{label}</label>
    <input type={type} className="w-full bg-slate-50 dark:bg-background-dark border border-slate-200 dark:border-white/10 rounded-2xl p-4 text-sm text-slate-900 dark:text-white focus:ring-primary transition-all" value={value} onChange={e => onChange?.(e.target.value)} placeholder={placeholder} />
  </div>
);

const ColorPicker = ({ color, onChange }: any) => {
  const presets = ['#00D1FF', '#FF5E00', '#ef4444', '#fbbf24', '#a855f7'];
  return (
    <div className="flex items-center gap-4">
      <div className="size-14 rounded-2xl border border-slate-200 dark:border-white/10 flex-shrink-0 shadow-lg transition-colors" style={{backgroundColor: color}}></div>
      <div className="flex flex-wrap gap-2">
        {presets.map(p => (
          <button key={p} onClick={() => onChange(p)} className={`size-10 rounded-xl transition-all ${color === p ? 'ring-2 ring-primary ring-offset-4 ring-offset-white dark:ring-offset-surface-dark scale-90' : 'opacity-60 hover:opacity-100'}`} style={{backgroundColor: p}} />
        ))}
        <div className="relative size-10 rounded-xl bg-gradient-to-tr from-pink-500 via-yellow-500 to-primary flex items-center justify-center overflow-hidden cursor-pointer hover:scale-105 transition-transform">
          <input type="color" className="absolute inset-0 opacity-0 cursor-pointer w-full h-full scale-150" value={color} onChange={e => onChange(e.target.value)} />
          <span className="material-symbols-outlined text-white text-sm pointer-events-none">colorize</span>
        </div>
      </div>
    </div>
  );
};

const NotifToggle = ({ active, label, description, onClick }: any) => (
  <button onClick={onClick} className="w-full flex items-center justify-between p-6 bg-slate-50 dark:bg-background-dark/30 border border-slate-200 dark:border-white/5 rounded-3xl hover:border-primary/20 transition-all text-left group">
    <div>
      <p className="text-sm font-black text-slate-900 dark:text-white group-hover:text-primary transition-colors">{label}</p>
      <p className="text-[10px] text-slate-400 dark:text-gray-500 font-bold uppercase mt-1 tracking-tight">{description}</p>
    </div>
    <div className={`w-14 h-8 rounded-full relative transition-all duration-300 ${active ? 'bg-primary' : 'bg-slate-300 dark:bg-white/10'}`}>
      <div className={`absolute top-1 size-6 rounded-full bg-white transition-all duration-300 shadow-md ${active ? 'left-7' : 'left-1'}`}></div>
    </div>
  </button>
);

const TeamMember = ({ name, role, onDelete, onNameChange }: any) => {
  const [isEditing, setIsEditing] = useState(false);
  const [localName, setLocalName] = useState(name);

  return (
    <div className="flex items-center justify-between p-4 bg-slate-50 dark:bg-background-dark/30 border border-slate-200 dark:border-white/5 rounded-2xl group hover:border-primary/20 transition-all">
      <div className="flex items-center gap-3 flex-1">
        <div className="size-10 rounded-full bg-slate-200 dark:bg-white/5 flex items-center justify-center text-xs font-black text-slate-500 uppercase overflow-hidden">
           {name.split(' ').map((n: string) => n[0]).join('')}
        </div>
        <div className="flex-1">
          {isEditing ? (
            <input 
                autoFocus
                className="w-full bg-transparent border-none p-0 text-sm font-bold text-slate-900 dark:text-white focus:ring-0" 
                value={localName} 
                onChange={(e) => setLocalName(e.target.value)}
                onBlur={() => {
                    setIsEditing(false);
                    onNameChange(localName);
                }}
            />
          ) : (
            <p className="text-sm font-bold text-slate-900 dark:text-white cursor-pointer" onClick={() => setIsEditing(true)}>{name}</p>
          )}
          <p className={`text-[10px] font-black uppercase tracking-widest ${role === 'Admin' ? 'text-primary' : 'text-blue-500'}`}>{role}</p>
        </div>
      </div>
      <div className="flex gap-2">
          <button onClick={() => setIsEditing(!isEditing)} className="size-8 rounded-lg bg-slate-200 dark:bg-white/5 hover:bg-primary/10 hover:text-primary opacity-0 group-hover:opacity-100 transition-all flex items-center justify-center">
             <span className="material-symbols-outlined text-sm">edit</span>
          </button>
          <button onClick={onDelete} className="size-8 rounded-lg bg-slate-200 dark:bg-white/5 hover:bg-red-500 hover:text-white opacity-0 group-hover:opacity-100 transition-all flex items-center justify-center">
             <span className="material-symbols-outlined text-sm">delete</span>
          </button>
      </div>
    </div>
  );
};

export default BrandCustomization;

import React, { useState, useEffect } from 'react';
import { UserRole } from './types';
import LoginView from './views/LoginView';
import CustomerAuthView from './views/CustomerAuthView';
import CustomerHome from './views/CustomerHome';
import StaffValidator from './views/StaffValidator';
import AdminDashboard from './views/AdminDashboard';
import CreatePool from './views/CreatePool';
import Leaderboard from './views/Leaderboard';
import Analytics from './views/Analytics';
import BrandCustomization from './views/BrandCustomization';
import GuessesView from './views/GuessesView';
import CouponsView from './views/CouponsView';
import PoolDetailView from './views/PoolDetailView';
import AdminPoolsView from './views/AdminPoolsView';
import AdminCouponsView from './views/AdminCouponsView';
import AdminCustomersView from './views/AdminCustomersView';
import AdminAlertsView from './views/AdminAlertsView';
import AdminPoolStatsView from './views/AdminPoolStatsView';
import CareerDetailsView from './views/CareerDetailsView';
import CustomerProfileView from './views/CustomerProfileView';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.GUEST);
  const [currentView, setCurrentView] = useState<string>('home');
  const [isCustomerAuth, setIsCustomerAuth] = useState(false);
  const [selectedPoolId, setSelectedPoolId] = useState<string | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(false); // Inicia no modo claro
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const [adminName, setAdminName] = useState('BarPlay Admin');
  const [adminLogo, setAdminLogo] = useState('https://iili.io/fsviySn.png'); 
  const [primaryColor, setPrimaryColor] = useState('#00D1FF');
  const [secondaryColor, setSecondaryColor] = useState('#FF5E00');

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  useEffect(() => {
    document.documentElement.style.setProperty('--primary', primaryColor);
    document.documentElement.style.setProperty('--primary-dark', primaryColor + 'cc');
    document.documentElement.style.setProperty('--secondary', secondaryColor);
  }, [primaryColor, secondaryColor]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const navigateToPool = (id: string) => {
    setSelectedPoolId(id);
  };

  const navigateToStats = (id: string) => {
    setSelectedPoolId(id);
    setCurrentView('admin-pool-stats');
  };

  const handleLogin = (newRole: UserRole) => {
    setRole(newRole);
    setIsCustomerAuth(false);
    setCurrentView('home');
    setIsSidebarOpen(false);
  };

  const openSidebar = () => setIsSidebarOpen(true);

  if (role === UserRole.GUEST && !isCustomerAuth) {
    return <LoginView onLogin={handleLogin} onCustomerAuth={() => setIsCustomerAuth(true)} />;
  }

  if (isCustomerAuth) {
    return <CustomerAuthView onLogin={handleLogin} onBack={() => setIsCustomerAuth(false)} />;
  }

  const Sidebar = () => (
    <>
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[60] lg:hidden"
          onClick={() => setIsSidebarOpen(false)}
        ></div>
      )}

      <aside className={`fixed lg:sticky top-0 left-0 z-[70] flex flex-col w-64 bg-white dark:bg-surface-dark border-r border-slate-200 dark:border-white/5 h-screen p-6 shadow-2xl lg:shadow-sm transition-transform duration-300 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="flex items-center justify-between mb-10">
          <div className="flex items-center justify-center w-full relative">
            <div className="w-48 h-28 flex items-center justify-center overflow-hidden">
               <img src={adminLogo} className="w-full h-full object-contain drop-shadow-[0_0_8px_rgba(0,209,255,0.4)]" alt="Logo" />
            </div>
          </div>
          <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden absolute top-0 right-0 size-8 flex items-center justify-center rounded-lg bg-slate-100 dark:bg-white/5 text-slate-500">
            <span className="material-symbols-outlined">close</span>
          </button>
        </div>

        <nav className="flex-1 space-y-2">
          <NavItem icon="dashboard" label={(role === UserRole.ADMIN) ? "Dashboard" : "Início"} view="home" active={currentView === 'home'} />
          {role === UserRole.ADMIN && (
            <>
              <NavItem icon="format_list_bulleted" label="Bolões" view="admin-pools" active={currentView === 'admin-pools'} />
              <NavItem icon="local_activity" label="Cupons" view="admin-coupons" active={currentView === 'admin-coupons'} />
              <NavItem icon="group" label="Clientes" view="admin-customers" active={currentView === 'admin-customers'} />
              <NavItem icon="bar_chart" label="Análises" view="analytics" active={currentView === 'analytics'} />
              <NavItem icon="settings" label="Marca" view="branding" active={currentView === 'branding'} />
            </>
          )}
          {role === UserRole.CUSTOMER && (
            <>
              <NavItem icon="receipt_long" label="Meus palpites" view="guesses" active={currentView === 'guesses'} />
              <NavItem icon="leaderboard" label="Ranking geral" view="ranking" active={currentView === 'ranking'} />
              <NavItem icon="local_activity" label="Meus cupons" view="coupons" active={currentView === 'coupons'} />
              <NavItem icon="person" label="Meus dados" view="profile" active={currentView === 'profile'} />
            </>
          )}
        </nav>

        <div className="mt-auto pt-6 border-t border-slate-100 dark:border-white/5 space-y-2">
          <button 
            onClick={toggleTheme}
            className="w-full flex items-center gap-3 p-3 rounded-xl font-bold text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-white/5 transition-all"
          >
            <span className="material-symbols-outlined">{isDarkMode ? 'light_mode' : 'dark_mode'}</span>
            <span>Modo {isDarkMode ? 'claro' : 'escuro'}</span>
          </button>
          <button onClick={() => { handleLogin(UserRole.GUEST); setIsSidebarOpen(false); }} className="w-full flex items-center gap-3 p-3 rounded-xl hover:bg-red-500/10 text-slate-400 hover:text-red-500 transition-colors font-bold">
            <span className="material-symbols-outlined">logout</span>
            <span>Sair</span>
          </button>
        </div>
      </aside>
    </>
  );

  const NavItem = ({ icon, label, view, active }: { icon: string, label: string, view: string, active: boolean }) => (
    <button 
      onClick={() => { setCurrentView(view); setIsSidebarOpen(false); }}
      className={`w-full flex items-center gap-3 p-3 rounded-xl font-bold transition-all ${active ? 'bg-primary text-background-dark shadow-lg shadow-primary/20' : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-white/5'}`}
    >
      <span className="material-symbols-outlined">{icon}</span>
      <span>{label}</span>
    </button>
  );

  return (
    <div className="min-h-screen bg-background-light dark:bg-background-dark text-slate-900 dark:text-white flex flex-col lg:flex-row transition-colors">
      <Sidebar />
      <main className="flex-1 overflow-y-auto no-scrollbar relative">
        <div className="max-w-7xl mx-auto min-h-full flex flex-col">
          {(() => {
            switch (currentView) {
              case 'home':
                if (role === UserRole.STAFF) return <StaffValidator onBack={() => setRole(UserRole.GUEST)} />;
                if (role === UserRole.ADMIN) return <AdminDashboard adminName={adminName} adminLogo={adminLogo} onNavigate={(v) => setCurrentView(v)} onLogout={() => setRole(UserRole.GUEST)} toggleTheme={toggleTheme} isDarkMode={isDarkMode} openSidebar={openSidebar} />;
                return <CustomerHome openSidebar={openSidebar} onNavigate={(v) => setCurrentView(v)} onSelectPool={navigateToPool} onLogout={() => setRole(UserRole.GUEST)} />;
              case 'admin-pools': return <AdminPoolsView onNavigate={(v) => setCurrentView(v)} onBack={() => setCurrentView('home')} onViewStats={navigateToStats} />;
              case 'admin-pool-stats': return <AdminPoolStatsView poolId={selectedPoolId} onBack={() => setCurrentView('admin-pools')} />;
              case 'admin-coupons': return <AdminCouponsView onNavigate={(v) => setCurrentView(v)} onBack={() => setCurrentView('home')} />;
              case 'admin-customers': return <AdminCustomersView onNavigate={(v) => setCurrentView(v)} onBack={() => setCurrentView('home')} />;
              case 'admin-alerts': return <AdminAlertsView onBack={() => setCurrentView('home')} />;
              case 'guesses': return <GuessesView openSidebar={openSidebar} onNavigate={(v) => setCurrentView(v)} />;
              case 'ranking': return <Leaderboard openSidebar={openSidebar} onNavigate={(v) => setCurrentView(v)} onBack={() => setCurrentView('home')} />;
              case 'career-details': return <CareerDetailsView onBack={() => setCurrentView('ranking')} />;
              case 'coupons': return <CouponsView openSidebar={openSidebar} onNavigate={(v) => setCurrentView(v)} />;
              case 'profile': return <CustomerProfileView openSidebar={openSidebar} />;
              case 'create-pool': return <CreatePool onBack={() => setCurrentView('home')} />;
              case 'analytics': return <Analytics onBack={() => setCurrentView('home')} />;
              case 'branding': return <BrandCustomization adminLogo={adminLogo} setAdminLogo={setAdminLogo} adminName={adminName} setAdminName={setAdminName} primaryColor={primaryColor} setPrimaryColor={setPrimaryColor} secondaryColor={secondaryColor} setSecondaryColor={setSecondaryColor} onBack={() => setCurrentView('home')} />;
              default: return <CustomerHome openSidebar={openSidebar} onNavigate={(v) => setCurrentView(v)} onSelectPool={navigateToPool} onLogout={() => setRole(UserRole.GUEST)} />;
            }
          })()}
        </div>

        {selectedPoolId && (
          <PoolDetailView poolId={selectedPoolId} onBack={() => setSelectedPoolId(null)} />
        )}
      </main>
    </div>
  );
};

export default App;

