const AdminCustomersView: React.FC<AdminCustomersViewProps> = ({ onNavigate, onBack }) => {
  const [customers, setCustomers] = useState<CustomerData[]>(INITIAL_CUSTOMERS);
  const [search, setSearch] = useState('');

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState<CustomerData | null>(null);
  const [formData, setFormData] = useState<Partial<CustomerData>>({
    name: '',
    email: '',
    phone: '',
    birthday: ''
  });

  const filteredCustomers = useMemo(() => {
    return customers.filter(c => 
      c.name.toLowerCase().includes(search.toLowerCase()) || 
      c.email.toLowerCase().includes(search.toLowerCase())
    );
  }, [customers, search]);

  const handleOpenModal = (customer?: CustomerData) => {
    if (customer) {
      setEditingCustomer(customer);
      setFormData(customer);
    } else {
      setEditingCustomer(null);
      setFormData({ name: '', email: '', phone: '', birthday: '' });
    }
    setIsModalOpen(true);
  };

  const handleSave = () => {
    if (editingCustomer) {
      setCustomers(prev => prev.map(c => c.id === editingCustomer.id ? { ...c, ...formData as CustomerData } : c));
    } else {
      setCustomers(prev => [{ id: Math.random().toString(36).substr(2, 9), poolsCount: 0, couponsCount: 0, totalSpent: 'R$ 0,00', ...formData as CustomerData }, ...prev]);
    }
    setIsModalOpen(false);
  };

  const formatBirthday = (dateStr: string) => {
    if (!dateStr) return '-';
    const parts = dateStr.split('-');
    if (parts.length === 3) {
      return `${parts[2]}/${parts[1]}/${parts[0]}`;
    }
    return dateStr;
  };

  const handleDelete = (id: string) => {
    if (window.confirm('Excluir cliente?')) setCustomers(prev => prev.filter(c => c.id !== id));
  };

  return (
    <div className="flex flex-col min-h-screen bg-background-light dark:bg-background-dark pb-24 lg:pb-12 px-6 lg:px-10 transition-colors">
      <header className="py-8 flex flex-col md:flex-row md:items-center justify-between gap-6 border-b border-slate-200 dark:border-white/5 mb-8">
        <div className="text-left">
          <h2 className="text-3xl font-black tracking-tight text-slate-900 dark:text-white">Gestão de Clientes</h2>
          <p className="text-sm font-bold text-slate-500 dark:text-gray-500 uppercase tracking-widest mt-1">Sua base de usuários ativos</p>
        </div>
        <button onClick={() => handleOpenModal()} className="h-12 px-6 bg-primary text-background-dark font-black rounded-2xl text-sm flex items-center justify-center gap-2 shadow-lg shadow-primary/20 hover:scale-105 transition-all">
          <span className="material-symbols-outlined">person_add</span> Adicionar cliente
        </button>
      </header>

      <div className="flex mb-8">
        <div className="relative flex-1">
          <span className="material-symbols-outlined absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">search</span>
          <input type="text" placeholder="Buscar por nome ou email..." className="w-full bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/10 rounded-2xl py-3.5 pl-12 pr-4 text-sm text-slate-900 dark:text-white focus:ring-primary shadow-sm" value={search} onChange={(e) => setSearch(e.target.value)} />
        </div>
      </div>

      <div className="bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/5 rounded-[32px] overflow-hidden shadow-sm overflow-x-auto no-scrollbar">
        <table className="w-full text-left border-collapse min-w-[1100px] table-fixed">
          <thead>
            <tr className="bg-slate-50 dark:bg-white/5">
              <th className="px-4 py-4 text-[10px] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest w-[200px]">Nome</th>
              <th className="px-4 py-4 text-[10px] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest w-[250px]">Email</th>
              <th className="px-4 py-4 text-[10px] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest w-[160px]">Celular</th>
              <th className="px-4 py-4 text-[10px] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest w-[120px]">Nasc.</th>
              <th className="px-4 py-4 text-[10px] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest w-[120px]">Total gasto</th>
              <th className="px-4 py-4 text-[10px] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest w-[100px] text-center">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 dark:divide-white/5">
            {filteredCustomers.map((c) => (
              <tr key={c.id} className="hover:bg-slate-50 dark:hover:bg-white/5 transition-colors">
                <td className="px-4 py-5 text-sm font-medium text-slate-900 dark:text-white truncate" title={c.name}>{c.name}</td>
                <td className="px-4 py-5 text-sm font-medium text-slate-500 dark:text-gray-400 truncate" title={c.email}>{c.email}</td>
                <td className="px-4 py-5 text-sm font-medium text-slate-400">{c.phone}</td>
                <td className="px-4 py-5 text-sm font-medium text-slate-500">{formatBirthday(c.birthday)}</td>
