                <InputGroup label="Nome" value={formData.name} onChange={v => setFormData({...formData, name: v})} />
                <InputGroup label="Email" value={formData.email} onChange={v => setFormData({...formData, email: v})} />
                <div className="grid grid-cols-2 gap-4">
