            <span className="material-symbols-outlined">logout</span>
            <span>Sair</span>
          </button>
        </div>
      </aside>
    </>
  );

  const NavItem = ({ icon, label, view, active }: { icon: string, label: string, view: string, active: boolean }) => (
    <button 
      onClick={() => { setCurrentView(view); setIsSidebarOpen(false); }}
      className={`w-full flex items-center gap-3 p-3 rounded-xl font-bold transition-all ${active ? 'bg-primary text-background-dark shadow-lg shadow-primary/20' : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-white/5'}`}
    >
      <span className="material-symbols-outlined">{icon}</span>
      <span>{label}</span>
    </button>
  );

  return (
    <div className="min-h-screen bg-background-light dark:bg-background-dark text-slate-900 dark:text-white flex flex-col lg:flex-row transition-colors">
      <Sidebar />
      <main className="flex-1 overflow-y-auto no-scrollbar relative">
        <div className="max-w-7xl mx-auto min-h-full flex flex-col">
          {(() => {
            switch (currentView) {
              case 'home':
                if (role === UserRole.STAFF) return <StaffValidator onBack={() => setRole(UserRole.GUEST)} />;
                if (role === UserRole.ADMIN) return <AdminDashboard adminName={adminName} adminLogo={adminLogo} onNavigate={(v) => setCurrentView(v)} onLogout={() => setRole(UserRole.GUEST)} toggleTheme={toggleTheme} isDarkMode={isDarkMode} openSidebar={openSidebar} />;
                return <CustomerHome openSidebar={openSidebar} onNavigate={(v) => setCurrentView(v)} onSelectPool={navigateToPool} onLogout={() => setRole(UserRole.GUEST)} />;
              case 'admin-pools': return <AdminPoolsView adminLogo={adminLogo} openSidebar={openSidebar} onNavigate={(v) => setCurrentView(v)} onBack={() => setCurrentView('home')} onViewStats={navigateToStats} />;
              case 'admin-pool-stats': return <AdminPoolStatsView adminLogo={adminLogo} poolId={selectedPoolId} onBack={() => setCurrentView('admin-pools')} />;
              case 'admin-coupons': return <AdminCouponsView adminLogo={adminLogo} openSidebar={openSidebar} onNavigate={(v) => setCurrentView(v)} onBack={() => setCurrentView('home')} />;
              case 'admin-customers': return <AdminCustomersView adminLogo={adminLogo} openSidebar={openSidebar} onNavigate={(v) => setCurrentView(v)} onBack={() => setCurrentView('home')} />;
              case 'admin-alerts': return <AdminAlertsView adminLogo={adminLogo} onBack={() => setCurrentView('home')} />;
              case 'guesses': return <GuessesView adminLogo={adminLogo} openSidebar={openSidebar} onNavigate={(v) => setCurrentView(v)} />;
              case 'ranking': return <Leaderboard adminLogo={adminLogo} openSidebar={openSidebar} onNavigate={(v) => setCurrentView(v)} onBack={() => setCurrentView('home')} />;
              case 'career-details': return <CareerDetailsView adminLogo={adminLogo} onBack={() => setCurrentView('ranking')} />;
              case 'coupons': return <CouponsView adminLogo={adminLogo} openSidebar={openSidebar} onNavigate={(v) => setCurrentView(v)} />;
              case 'profile': return <CustomerProfileView adminLogo={adminLogo} openSidebar={openSidebar} />;
              case 'create-pool': return <CreatePool onBack={() => setCurrentView('home')} />;
              case 'analytics': return <Analytics adminLogo={adminLogo} openSidebar={openSidebar} onBack={() => setCurrentView('home')} />;
              case 'branding': return <BrandCustomization adminLogo={adminLogo} setAdminLogo={setAdminLogo} adminName={adminName} setAdminName={setAdminName} primaryColor={primaryColor} setPrimaryColor={setPrimaryColor} secondaryColor={secondaryColor} setSecondaryColor={setSecondaryColor} onBack={() => setCurrentView('home')} />;
              default: return <CustomerHome openSidebar={openSidebar} onNavigate={(v) => setCurrentView(v)} onSelectPool={navigateToPool} onLogout={() => setRole(UserRole.GUEST)} />;
            }
          })()}
        </div>

        {/* O modal de palpite só deve abrir se o papel for CUSTOMER e um ID estiver selecionado */}
        {selectedPoolId && role === UserRole.CUSTOMER && (
          <PoolDetailView poolId={selectedPoolId} onBack={() => setSelectedPoolId(null)} />
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';

interface PoolData {
  id: string;
  name: string;
  status: 'ativo' | 'pendente' | 'finalizado';
  participants: number;
  endDate: string;
  endTime: string;
  prize: string;
  entry: string;
  type: string;
}

interface AdminPoolsViewProps {
  onNavigate: (view: string) => void;
  onBack: () => void;
  onViewStats: (id: string) => void;
  openSidebar: () => void;
  adminLogo: string;
}

const INITIAL_POOLS: PoolData[] = [
  { id: '1', name: 'Final da Champions', status: 'ativo', participants: 45, endDate: '2024-06-01', endTime: '16:00', prize: 'R$ 500,00', entry: 'R$ 20,00', type: 'Futebol' },
  { id: '2', name: 'NBA Finals - G1', status: 'pendente', participants: 12, endDate: '2024-06-05', endTime: '21:00', prize: 'Balde de Spaten', entry: 'Grátis*', type: 'Basquete' },
  { id: '3', name: 'UFC 302: Makhachev vs Poirier', status: 'finalizado', participants: 89, endDate: '2024-05-28', endTime: '23:00', prize: 'Rodízio de Chopp', entry: 'R$ 15,00', type: 'MMA' },
  { id: '4', name: 'Super Bowl LVIII', status: 'finalizado', participants: 156, endDate: '2024-02-11', endTime: '20:30', prize: 'TV 55"', entry: 'R$ 50,00', type: 'NFL' },
];

const AdminPoolsView: React.FC<AdminPoolsViewProps> = ({ onNavigate, onBack, onViewStats, openSidebar, adminLogo }) => {
  const [pools, setPools] = useState<PoolData[]>(INITIAL_POOLS);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('Todos');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingPool, setEditingPool] = useState<PoolData | null>(null);

  const [formData, setFormData] = useState<{
    name: string;
    endDate: string;
    endTime: string;
    prize: string;
    entry: string;
    type: string;
    status: PoolData['status'];
  }>({
    name: '',
    endDate: '',
    endTime: '',
    prize: '',
    entry: '',
    type: 'Futebol',
    status: 'pendente'
  });

  const filteredPools = useMemo(() => {
    return pools.filter(p => {
      const matchesSearch = p.name.toLowerCase().includes(search.toLowerCase());
      let normalizedStatus = statusFilter.toLowerCase();
      if (normalizedStatus === 'ativos') normalizedStatus = 'ativo';
      if (normalizedStatus === 'pendentes') normalizedStatus = 'pendente';
      if (normalizedStatus === 'finalizados') normalizedStatus = 'finalizado';

      const isStatusMatch = statusFilter === 'Todos' || p.status === normalizedStatus;
      return matchesSearch && isStatusMatch;
    });
  }, [pools, search, statusFilter]);

  const handleOpenModal = (pool?: PoolData) => {
    if (pool) {
      setEditingPool(pool);
      setFormData({
        name: pool.name,
        endDate: pool.endDate,
        endTime: pool.endTime,
        prize: pool.prize,
        entry: pool.entry,
        type: pool.type,
        status: pool.status
      });
    } else {
      setEditingPool(null);
      setFormData({ name: '', endDate: '', endTime: '', prize: '', entry: '', type: 'Futebol', status: 'pendente' });
    }
    setIsModalOpen(true);
  };

  const handleSave = () => {
    if (editingPool) {
      setPools(prev => prev.map(p => p.id === editingPool.id ? { ...p, ...formData } : p));
    } else {
      setPools(prev => [{ id: Math.random().toString(36).substr(2, 9), participants: 0, ...formData }, ...prev]);
    }
    setIsModalOpen(false);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'ativo': return 'bg-primary/20 text-primary border-primary/30';
      case 'pendente': return 'bg-yellow-500/20 text-yellow-600 dark:text-yellow-400 border-yellow-500/30';
      case 'finalizado': return 'bg-slate-100 dark:bg-white/10 text-slate-500 dark:text-gray-400 border-slate-200 dark:border-white/5';
      default: return '';
    }
  };

  return (
