const DEFAULTS = {
  barInfo: {
    name: 'BarPlay HQ',
    phone: '(11) 98877-6655',
    address: 'Rua dos Esportes, 123 - Jardins, SP',
    description: 'O melhor bar de esportes da região com transmissões ao vivo e prêmios exclusivos.'
  },
  primaryColor: '#00D1FF',
