  onBack, 
  adminLogo, 
  setAdminLogo, 
  adminName, 
  setAdminName,
  primaryColor,
  setPrimaryColor,
  secondaryColor,
  setSecondaryColor,
  openSidebar
}) => {
  const [activeTab, setActiveTab] = useState<SubPage>('geral');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [barInfo, setBarInfo] = useState(DEFAULTS.barInfo);
  const [notifs, setNotifs] = useState(DEFAULTS.notifs);

  const [team, setTeam] = useState<TeamMemberData[]>([
    { id: '1', name: adminName, role: 'Admin' },
    { id: '2', name: 'Maria Souza', role: 'Staff' },
    { id: '3', name: 'Carlos Roberto', role: 'Staff' },
