  const toggleNotif = (key: keyof typeof notifs) => {
    setNotifs(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        alert("O arquivo é muito grande! Máximo de 2MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setAdminLogo(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleUpdateAdminMemberName = (id: string, newName: string) => {
    setTeam(prev => prev.map(m => {
        if (m.id === id) {
            if (m.role === 'Admin') setAdminName(newName);
            return { ...m, name: newName };
        }
        return m;
    }));
  };

  const handleSaveAll = () => {
    alert("Configurações salvas com sucesso!");
    onBack();
  };

  const handleReset = () => {
    if (window.confirm("Resetar para os padrões?")) {
      setBarInfo(DEFAULTS.barInfo);
      setPrimaryColor(DEFAULTS.primaryColor);
      setSecondaryColor(DEFAULTS.secondaryColor);
      setNotifs(DEFAULTS.notifs);
      setAdminLogo(DEFAULTS.barInfo.name);
    }
  };

  const handleAddMember = () => {
    if (!newMember.name) return;
    const member: TeamMemberData = {
      id: Math.random().toString(36).substr(2, 9),
      name: newMember.name,
      role: newMember.role
    };
    setTeam(prev => [...prev, member]);
    if (member.role === 'Admin') setAdminName(member.name);
    setNewMember({ name: '', role: 'Staff' });
    setIsTeamModalOpen(false);
