  { id: 'ev4', externalId: 'API-4491', modality: 'Futebol', league: 'Brasileirão', competitors: ['Flamengo', 'Vasco'], flags: ['https://flagcdn.com/w40/br.png', 'https://flagcdn.com/w40/br.png'], date: '2024-06-02', time: '16:00', status: 'agendado', activated: true },
];

const AdminEventsView: React.FC<AdminEventsViewProps> = ({ onBack, openSidebar, adminLogo }) => {
  const [events, setEvents] = useState<SportEvent[]>(MOCK_EVENTS);
  const [activeTab, setActiveTab] = useState<'Futebol' | 'Basquete' | 'MMA' | 'Tudo'>('Tudo');
  const [isActivationModalOpen, setIsActivationModalOpen] = useState(false);
  const [selectedEvent, setSelectedEvent] = useState<SportEvent | null>(null);

  const filteredEvents = useMemo(() => {
    if (activeTab === 'Tudo') return events;
    return events.filter(e => e.modality === activeTab);
  }, [events, activeTab]);

  const handleActivateClick = (event: SportEvent) => {
    setSelectedEvent(event);
    setIsActivationModalOpen(true);
  };

  const confirmActivation = () => {
    if (!selectedEvent) return;
    setEvents(prev => prev.map(e => e.id === selectedEvent.id ? { ...e, activated: true } : e));
    setIsActivationModalOpen(false);
    // Simulação de criação automática de bolão
    alert(`Evento ${selectedEvent.competitors.join(' vs ')} ativado com sucesso! Monitoramento automático iniciado.`);
  };

  return (
    <div className="flex flex-col min-h-screen bg-background-light dark:bg-background-dark pb-24 lg:pb-12 px-6 lg:px-10 transition-colors">
