            <span className="material-symbols-outlined">menu</span>
          </button>
          <img src={adminLogo} className="size-10 object-contain" alt="Logo" />
          <div>
            <h2 className="text-3xl font-black tracking-tight text-slate-900 dark:text-white">Central de Eventos</h2>
            <p className="text-sm font-bold text-slate-500 dark:text-gray-500 uppercase tracking-widest mt-1 leading-none">Resultados e palpites 100% automáticos</p>
          </div>
        </div>
      </header>

      <div className="flex flex-wrap gap-2 mb-8">
        {['Tudo', 'Futebol', 'Basquete', 'MMA'].map((tab) => (
          <button 
            key={tab}
            onClick={() => setActiveTab(tab as any)}
            className={`px-6 py-2.5 rounded-2xl text-xs font-black transition-all border ${activeTab === tab ? 'bg-primary text-background-dark border-primary shadow-lg shadow-primary/20' : 'bg-white dark:bg-surface-dark text-slate-500 border-slate-200 dark:border-white/10'}`}
          >
            {tab}
          </button>
        ))}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredEvents.map((e) => (
          <div key={e.id} className={`bg-white dark:bg-surface-dark border ${e.activated ? 'border-primary/40' : 'border-slate-200 dark:border-white/5'} rounded-[32px] p-6 shadow-sm flex flex-col group relative overflow-hidden transition-all hover:scale-[1.01]`}>
            {e.activated && (
              <div className="absolute top-0 right-0 px-4 py-1.5 bg-primary text-background-dark text-[10px] font-black uppercase rounded-bl-2xl flex items-center gap-2">
                <span className="relative flex h-2 w-2">
                  <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-background-dark opacity-75"></span>
                  <span className="relative inline-flex rounded-full h-2 w-2 bg-background-dark"></span>
