                   {typeof e.flags[0] === 'string' && e.flags[0].startsWith('http') ? <img src={e.flags[0]} className="size-8" /> : e.flags[0]}
                </div>
                <p className="text-xs font-black text-slate-900 dark:text-white truncate">{e.competitors[0]}</p>
              </div>
              <span className="text-sm font-black text-slate-300 dark:text-gray-700">VS</span>
              <div className="flex-1 text-center">
                <div className="size-16 mx-auto rounded-full bg-slate-50 dark:bg-background-dark flex items-center justify-center text-xl mb-2 border border-slate-100 dark:border-white/5 shadow-inner">
                   {typeof e.flags[1] === 'string' && e.flags[1].startsWith('http') ? <img src={e.flags[1]} className="size-8" /> : e.flags[1]}
                </div>
                <p className="text-xs font-black text-slate-900 dark:text-white truncate">{e.competitors[1]}</p>
              </div>
            </div>

            <div className="mt-auto pt-6 border-t border-slate-100 dark:border-white/5 flex items-center justify-between">
               <div className="text-left">
                 <p className="text-[10px] font-black text-slate-400 dark:text-gray-500 uppercase">Data e Horário</p>
                 <p className="text-xs font-black text-slate-900 dark:text-white">{new Date(e.date).toLocaleDateString('pt-BR')} às {e.time}</p>
               </div>
               {e.activated ? (
                 <button className="h-10 px-4 bg-slate-100 dark:bg-white/5 text-slate-400 rounded-xl text-[10px] font-black uppercase cursor-default">Gerenciando...</button>
               ) : (
                 <button 
                  onClick={() => handleActivateClick(e)}
                  className="h-10 px-5 bg-primary text-background-dark rounded-xl text-[10px] font-black uppercase hover:scale-105 transition-all shadow-lg shadow-primary/20"
                 >
                   Ativar no meu bar
                 </button>
               )}
            </div>
          </div>
        ))}
      </div>

      {isActivationModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 text-left">
          <div className="absolute inset-0 bg-background-dark/95 backdrop-blur-md" onClick={() => setIsActivationModalOpen(false)}></div>
          <div className="relative z-10 w-full max-w-xl bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/10 rounded-[40px] shadow-2xl animate-in fade-in zoom-in duration-300 overflow-hidden">
             <div className="p-8 border-b border-slate-200 dark:border-white/5 flex items-center justify-between text-slate-900 dark:text-white">
                <h3 className="text-2xl font-black uppercase tracking-tight">Configuração de Bolão</h3>
                <button onClick={() => setIsActivationModalOpen(false)} className="material-symbols-outlined">close</button>
             </div>
             <div className="p-8 space-y-6">
                <div className="p-4 rounded-2xl bg-primary/5 border border-primary/10">
                   <p className="text-[10px] font-black text-primary uppercase mb-1">Evento Vinculado</p>
                   <p className="text-base font-black text-slate-900 dark:text-white">{selectedEvent?.competitors.join(' vs ')}</p>
                </div>

                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest mb-2 block">Tipo de Palpite</label>
                  <div className="grid grid-cols-2 gap-3">
                     <button className="p-4 rounded-2xl bg-primary text-background-dark font-black text-xs border border-primary">Placar Exato</button>
                     <button className="p-4 rounded-2xl bg-slate-100 dark:bg-white/5 text-slate-400 font-black text-xs border border-transparent">Vencedor (1x2)</button>
                  </div>
                </div>

                <div>
                  <label className="text-[10px] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest mb-2 block">Prêmio Automático</label>
                  <input className="w-full bg-slate-50 dark:bg-background-dark border border-slate-200 dark:border-white/10 rounded-2xl p-4 text-sm text-slate-900 dark:text-white" placeholder="Ex: Rodízio de Chopp" />
                </div>

                <div className="flex items-start gap-3 p-4 bg-yellow-500/10 rounded-2xl border border-yellow-500/20">
                   <span className="material-symbols-outlined text-yellow-500 text-sm">info</span>
                   <p className="text-[10px] font-bold text-yellow-600 dark:text-yellow-400 uppercase leading-tight">Palpites encerrarão automaticamente 10 minutos antes do início do evento ({selectedEvent?.time}).</p>
                </div>
             </div>
             <div className="p-8 border-t border-slate-200 dark:border-white/5 flex gap-4">
                <button onClick={() => setIsActivationModalOpen(false)} className="flex-1 py-4 bg-slate-50 dark:bg-white/5 rounded-2xl font-black text-slate-900 dark:text-white uppercase">Cancelar</button>
                <button onClick={confirmActivation} className="flex-1 py-4 bg-primary text-background-dark rounded-2xl font-black shadow-xl uppercase">Confirmar Ativação</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminEventsView;

import React, { useState, useRef } from 'react';

interface BrandCustomizationProps {
  onBack: () => void;
  adminLogo: string;
  setAdminLogo: (logo: string) => void;
  adminName: string;
  setAdminName: (name: string) => void;
  primaryColor: string;
  setPrimaryColor: (color: string) => void;
  secondaryColor: string;
  setSecondaryColor: (color: string) => void;
  openSidebar?: () => void;
}

type SubPage = 'geral' | 'aparencia' | 'notificacoes' | 'mensagens' | 'seguranca';

interface TeamMemberData {
  id: string;
  name: string;
  role: 'Admin' | 'Staff';
}

const DEFAULTS = {
  barInfo: {
    name: 'BarPlay HQ',
    phone: '(11) 98877-6655',
    address: 'Rua dos Esportes, 123 - Jardins, SP',
    description: 'O melhor bar de esportes da região com transmissões ao vivo e prêmios exclusivos.'
  },
  primaryColor: '#00D1FF',
  secondaryColor: '#FF5E00',
  notifs: {
    participants: true,
    coupons: true,
    poolsEnding: true,
    reports: false
  },
  templates: {
    winner: 'Parabéns! Você venceu o bolão do evento {evento} no {bar}. Apresente esta mensagem no balcão para resgatar seu prêmio: {premio}.',
    loser: 'Quase! Não foi dessa vez no bolão de {evento}. Mas não desanima: aqui está um cupom especial para sua próxima visita no {bar}!'
  }
};

const BrandCustomization: React.FC<BrandCustomizationProps> = ({ 
  onBack, 
  adminLogo, 
  setAdminLogo, 
  adminName, 
  setAdminName,
  primaryColor,
  setPrimaryColor,
  secondaryColor,
  setSecondaryColor,
  openSidebar
}) => {
  const [activeTab, setActiveTab] = useState<SubPage>('geral');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [barInfo, setBarInfo] = useState(DEFAULTS.barInfo);
  const [notifs, setNotifs] = useState(DEFAULTS.notifs);
  const [templates, setTemplates] = useState(DEFAULTS.templates);

  const [team, setTeam] = useState<TeamMemberData[]>([
    { id: '1', name: adminName, role: 'Admin' },
    { id: '2', name: 'Maria Souza', role: 'Staff' },
    { id: '3', name: 'Carlos Roberto', role: 'Staff' },
  ]);
  const [isTeamModalOpen, setIsTeamModalOpen] = useState(false);
  const [newMember, setNewMember] = useState({ name: '', role: 'Staff' as 'Admin' | 'Staff' });

  const toggleNotif = (key: keyof typeof notifs) => {
    setNotifs(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        alert("O arquivo é muito grande! Máximo de 2MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setAdminLogo(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleUpdateAdminMemberName = (id: string, newName: string) => {
    setTeam(prev => prev.map(m => {
        if (m.id === id) {
            if (m.role === 'Admin') setAdminName(newName);
            return { ...m, name: newName };
        }
        return m;
    }));
  };

  const handleSaveAll = () => {
    alert("Configurações salvas com sucesso!");
    onBack();
  };

  const handleReset = () => {
    if (window.confirm("Resetar para os padrões?")) {
      setBarInfo(DEFAULTS.barInfo);
      setPrimaryColor(DEFAULTS.primaryColor);
      setSecondaryColor(DEFAULTS.secondaryColor);
      setNotifs(DEFAULTS.notifs);
      setTemplates(DEFAULTS.templates);
      setAdminLogo(DEFAULTS.barInfo.name);
    }
  };

  const handleAddMember = () => {
    if (!newMember.name) return;
    const member: TeamMemberData = {
      id: Math.random().toString(36).substr(2, 9),
      name: newMember.name,
      role: newMember.role
    };
    setTeam(prev => [...prev, member]);
    if (member.role === 'Admin') setAdminName(member.name);
    setNewMember({ name: '', role: 'Staff' });
    setIsTeamModalOpen(false);
  };

  const handleDeleteMember = (id: string) => {
    if (window.confirm("Remover este membro?")) {
      setTeam(prev => prev.filter(m => m.id !== id));
    }
  };

  return (
    <div className="flex flex-col min-h-full bg-background-light dark:bg-background-dark font-display relative overflow-y-visible transition-colors">
      <header className="py-8 px-6 lg:px-10 border-b border-slate-200 dark:border-white/5 bg-white/90 dark:bg-background-dark/90 backdrop-blur-xl sticky top-0 z-40">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 max-w-7xl mx-auto w-full">
          <div className="flex items-center gap-4 text-left">
            <button onClick={openSidebar} className="lg:hidden size-12 flex items-center justify-center rounded-2xl bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/10 shadow-sm text-slate-900 dark:text-white">
              <span className="material-symbols-outlined">menu</span>
            </button>
            <img src={adminLogo} className="size-10 object-contain" alt="Logo" />
            <div>
              <h2 className="text-3xl font-black tracking-tight text-slate-900 dark:text-white leading-tight">Gestão da Marca</h2>
              <p className="text-sm font-bold text-slate-500 dark:text-gray-500 uppercase tracking-widest mt-1 leading-none">Personalize a identidade do seu negócio</p>
            </div>
          </div>

          <div className="flex bg-slate-100 dark:bg-surface-dark p-1 rounded-2xl border border-slate-200 dark:border-white/10 overflow-x-auto no-scrollbar">
            <TabButton active={activeTab === 'geral'} label="Geral" onClick={() => setActiveTab('geral')} icon="info" />
            <TabButton active={activeTab === 'aparencia'} label="Aparência" onClick={() => setActiveTab('aparencia')} icon="palette" />
            <TabButton active={activeTab === 'mensagens'} label="Automação" onClick={() => setActiveTab('mensagens')} icon="chat_bubble" />
            <TabButton active={activeTab === 'notificacoes'} label="Notificações" onClick={() => setActiveTab('notificacoes')} icon="notifications" />
            <TabButton active={activeTab === 'seguranca'} label="Segurança" onClick={() => setActiveTab('seguranca')} icon="shield" />
          </div>
        </div>
      </header>

      <div className="p-6 lg:p-10 max-w-7xl mx-auto w-full pb-60 overflow-visible text-left">
        {activeTab === 'geral' && (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 animate-in fade-in slide-in-from-bottom-4 duration-500 overflow-visible">
            <section className="bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/5 rounded-[40px] p-8 shadow-sm h-fit">
              <h3 className="text-xl font-black mb-8 flex items-center gap-2 text-slate-900 dark:text-white">
                <span className="material-symbols-outlined text-primary">storefront</span>
                Informações do bar
              </h3>
              <div className="space-y-6">
                <InputGroup label="Nome do estabelecimento" value={barInfo.name} onChange={(v: string) => setBarInfo({...barInfo, name: v})} />
                <InputGroup label="Telefone de contato" value={barInfo.phone} onChange={(v: string) => setBarInfo({...barInfo, phone: v})} />
