              >
                {adminLogo ? (
                  <img src={adminLogo} alt="Logo preview" className="max-h-32 object-contain mb-4" />
                ) : (
                  <span className="material-symbols-outlined text-5xl text-slate-300 dark:text-gray-600 mb-4 group-hover:text-primary transition-colors">cloud_upload</span>
                )}
                <p className="text-sm font-bold text-slate-400 dark:text-gray-400">{adminLogo ? 'Substituir logotipo' : 'Clique para fazer upload'}</p>
              </div>
            </section>
          </div>
        )}

        {activeTab === 'mensagens' && (
          <div className="max-w-3xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500 overflow-visible">
             <section className="bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/5 rounded-[40px] p-8 shadow-sm">
                <h3 className="text-xl font-black mb-8 flex items-center gap-2 text-slate-900 dark:text-white">
                  <span className="material-symbols-outlined text-primary">chat_bubble</span>
                  Mensagens Automáticas
                </h3>
                <div className="space-y-8">
                   <div>
                     <label className="text-[10px] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest mb-2 block">Template: Ganhadores</label>
                     <textarea 
                        className="w-full bg-slate-50 dark:bg-background-dark border border-slate-200 dark:border-white/10 rounded-2xl p-4 text-sm text-slate-900 dark:text-white focus:ring-primary min-h-[100px]"
