                   </div>
                   <div className="p-4 bg-primary/5 rounded-2xl border border-primary/10">
                      <p className="text-[10px] font-black text-primary uppercase mb-2">Variáveis Suportadas</p>
                      <div className="flex flex-wrap gap-2">
                         {['{evento}', '{bar}', '{premio}', '{vendedor}'].map(v => (
