                         ))}
                      </div>
                   </div>
                </div>
             </section>
          </div>
        )}

        {activeTab === 'aparencia' && (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <section className="bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/5 rounded-[40px] p-8 shadow-sm h-fit text-slate-900 dark:text-white">
              <h3 className="text-xl font-black mb-8 flex items-center gap-2">
