          <button onClick={handleReset} className="flex-1 py-4 bg-slate-100 dark:bg-white/5 hover:bg-slate-200 dark:hover:bg-white/10 text-slate-900 dark:text-white font-black rounded-2xl transition-all uppercase tracking-tight">
            Resetar padrões
          </button>
          <button onClick={handleSaveAll} className="flex-1 py-4 bg-primary text-background-dark font-black rounded-2xl shadow-2xl shadow-primary/30 hover:scale-[1.02] transition-all flex items-center justify-center gap-2 uppercase tracking-tight">
            <span className="material-symbols-outlined font-black">save</span>
            Salvar alterações
          </button>
        </div>
      </div>

      {isTeamModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 text-left">
          <div className="absolute inset-0 bg-background-dark/95 backdrop-blur-md" onClick={() => setIsTeamModalOpen(false)}></div>
          <div className="relative z-10 w-full max-w-md bg-white dark:bg-surface-dark border border-slate-200 dark:border-white/10 rounded-[40px] shadow-2xl animate-in fade-in zoom-in duration-300">
            <div className="p-8 border-b border-slate-200 dark:border-white/5 flex items-center justify-between text-slate-900 dark:text-white">
              <h3 className="text-2xl font-black uppercase tracking-tight">Novo membro</h3>
              <button onClick={() => setIsTeamModalOpen(false)} className="size-10 flex items-center justify-center"><span className="material-symbols-outlined">close</span></button>
            </div>
            <div className="p-8 space-y-6">
              <InputGroup label="Nome" value={newMember.name} onChange={v => setNewMember({...newMember, name: v})} />
              <div>
                <label className="text-[10px] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest mb-2 block">Cargo / permissão</label>
                <select className="w-full bg-slate-50 dark:bg-background-dark border border-slate-200 dark:border-white/10 rounded-2xl p-4 text-sm text-slate-900 dark:text-white focus:ring-primary" value={newMember.role} onChange={e => setNewMember({...newMember, role: e.target.value as any})}>
                  <option value="Staff">Staff (Validador)</option>
                  <option value="Admin">Administrador (Total)</option>
                </select>
              </div>
            </div>
            <div className="p-8 border-t border-slate-100 dark:border-white/5 flex gap-4">
              <button onClick={() => setIsTeamModalOpen(false)} className="flex-1 py-4 bg-slate-100 dark:bg-white/5 rounded-2xl font-black text-slate-900 dark:text-white uppercase tracking-tight">Cancelar</button>
              <button onClick={handleAddMember} className="flex-1 py-4 bg-primary text-background-dark rounded-2xl font-black shadow-xl shadow-primary/20 uppercase tracking-tight">Adicionar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const TabButton = ({ active, label, onClick, icon }: any) => (
  <button onClick={onClick} className={`px-6 py-2.5 rounded-xl text-xs font-black transition-all flex items-center gap-2 whitespace-nowrap ${active ? 'bg-primary text-background-dark shadow-xl' : 'text-slate-500 dark:text-gray-500 hover:text-slate-900 dark:hover:text-white'}`}>
    <span className="material-symbols-outlined text-sm">{icon}</span>
    {label}
  </button>
);

const InputGroup = ({ label, value, onChange, type = "text", placeholder }: any) => (
  <div>
    <label className="text-[10px] font-black text-slate-400 dark:text-gray-500 uppercase tracking-widest mb-2 block">{label}</label>
    <input type={type} className="w-full bg-slate-50 dark:bg-background-dark border border-slate-200 dark:border-white/10 rounded-2xl p-4 text-sm text-slate-900 dark:text-white focus:ring-primary transition-all" value={value} onChange={e => onChange?.(e.target.value)} placeholder={placeholder} />
  </div>
);

const ColorPicker = ({ color, onChange }: any) => {
  const presets = ['#00D1FF', '#FF5E00', '#ef4444', '#fbbf24', '#a855f7'];
  return (
    <div className="flex items-center gap-4">
      <div className="size-14 rounded-2xl border border-slate-200 dark:border-white/10 flex-shrink-0 shadow-lg transition-colors" style={{backgroundColor: color}}></div>
      <div className="flex flex-wrap gap-2">
        {presets.map(p => (
          <button key={p} onClick={() => onChange(p)} className={`size-10 rounded-xl transition-all ${color === p ? 'ring-2 ring-primary ring-offset-4 ring-offset-white dark:ring-offset-surface-dark scale-90' : 'opacity-60 hover:opacity-100'}`} style={{backgroundColor: p}} />
        ))}
        <div className="relative size-10 rounded-xl bg-gradient-to-tr from-pink-500 via-yellow-500 to-primary flex items-center justify-center overflow-hidden cursor-pointer hover:scale-105 transition-transform">
          <input type="color" className="absolute inset-0 opacity-0 cursor-pointer w-full h-full scale-150" value={color} onChange={e => onChange(e.target.value)} />
          <span className="material-symbols-outlined text-white text-sm pointer-events-none">colorize</span>
        </div>
      </div>
    </div>
  );
};

const NotifToggle = ({ active, label, description, onClick }: any) => (
  <button onClick={onClick} className="w-full flex items-center justify-between p-6 bg-slate-50 dark:bg-background-dark/30 border border-slate-200 dark:border-white/5 rounded-3xl hover:border-primary/20 transition-all text-left group">
    <div>
      <p className="text-sm font-bold text-slate-900 dark:text-white group-hover:text-primary transition-colors">{label}</p>
      <p className="text-[10px] text-slate-400 dark:text-gray-500 font-bold uppercase mt-1 tracking-tight">{description}</p>
    </div>
    <div className={`w-14 h-8 rounded-full relative transition-all duration-300 ${active ? 'bg-primary' : 'bg-slate-300 dark:bg-white/10'}`}>
      <div className={`absolute top-1 size-6 rounded-full bg-white transition-all duration-300 shadow-md ${active ? 'left-7' : 'left-1'}`}></div>
    </div>
  </button>
);

const TeamMember = ({ name, role, onDelete, onNameChange }: any) => {
  const [isEditing, setIsEditing] = useState(false);
  const [localName, setLocalName] = useState(name);

  return (
    <div className="flex items-center justify-between p-4 bg-slate-50 dark:bg-background-dark/30 border border-slate-200 dark:border-white/5 rounded-2xl group hover:border-primary/20 transition-all">
      <div className="flex items-center gap-3 flex-1">
        <div className="size-10 rounded-full bg-slate-200 dark:bg-white/5 flex items-center justify-center text-xs font-black text-slate-500 uppercase overflow-hidden">
           {name.split(' ').map((n: string) => n[0]).join('')}
        </div>
        <div className="flex-1 text-left">
          {isEditing ? (
            <input 
                autoFocus
                className="w-full bg-transparent border-none p-0 text-sm font-bold text-slate-900 dark:text-white focus:ring-0" 
                value={localName} 
                onChange={(e) => setLocalName(e.target.value)}
                onBlur={() => {
                    setIsEditing(false);
                    onNameChange(localName);
                }}
            />
          ) : (
            <p className="text-sm font-bold text-slate-900 dark:text-white cursor-pointer" onClick={() => setIsEditing(true)}>{name}</p>
          )}
          <p className={`text-[10px] font-black uppercase tracking-widest ${role === 'Admin' ? 'text-primary' : 'text-blue-500'}`}>{role}</p>
        </div>
      </div>
      <div className="flex gap-2">
          <button onClick={() => setIsEditing(!isEditing)} className="size-8 rounded-lg bg-slate-200 dark:bg-white/5 hover:bg-primary/10 hover:text-primary opacity-0 group-hover:opacity-100 transition-all flex items-center justify-center">
             <span className="material-symbols-outlined text-sm">edit</span>
          </button>
          <button onClick={onDelete} className="size-8 rounded-lg bg-slate-200 dark:bg-white/5 hover:bg-red-500 hover:text-white opacity-0 group-hover:opacity-100 transition-all flex items-center justify-center">
             <span className="material-symbols-outlined text-sm">delete</span>
          </button>
      </div>
    </div>
  );
};

export default BrandCustomization;
